    pub(crate) const CAPTAIN: usize = 0x4a20;
    /// i8[11]: the penalty takers, in order (row of each).
    pub(crate) const PENALTY_ORDER: usize = 0x4a54;
    /// The undo copy of the team data and the clipboard copy.
