    /// u32: there is something to undo.
    pub(crate) const CAN_UNDO: usize = 0xc4de;
    /// Inside a team data block: its 20 match players (0x1be bytes each).
    pub(crate) const TEAM_PLAYERS: usize = 0x18f1;
