type TsTextAreaLinks = unsafe extern "C" fn(u32, u32, u32, u32, u32, u32, u32, u32, u32, usize, ...);
/// The final confirmation screen opener (`transfer_screens_open_confirm_transfer_screen`, 0x8f2e10, cdecl(slot,
