// ---------- batch 318: the Football Association meeting screen (fifa_confed.cpp) ----------

/// The screen manager's flag at +0x3834 (0xb77c84) that the dialog handlers check first: set, the handler clears the
/// pending command argument [`G_PENDING_COMMAND_ARG`] and closes (a network game's answer) [inference].
const TEL34_SCREEN_DIALOG_FLAG: usize = 0xb77c84;

/// Rule: opening the Football Association meeting screen of a club: parameter 0 = the club's index, 1 and 2 cleared.
///
/// `open_screen` (builder 0x58ad30, handler 0x58b0f0, single instance, leave 0x5a8f60 (the shared empty routine), no
/// exit); when it opens, parameter 0 = the club record's id (+0), parameters 1 and 2 = 0.
/// Original: `fa_meeting_open_screen` (0x58acd0, fifa_confed.cpp, cdecl).
pub(crate) unsafe extern "C" fn fa_meeting_open_screen(club: usize) {
    if exe::screenmanager_open_screen(G_SCREEN_MANAGER, 0x58ad30usize, 0x58b0f0usize, 1, 0x5a8f60usize, 0) != 0 {
        covered!("tel34_5 open fa meeting");
        set_screen_param(0, read_usize(club));
        set_screen_param(1, 0);
        set_screen_param(2, 0);
    }
}

/// Rule: the Football Association meeting screen: the club's manager in the title, the explanation, the two requests
/// to choose from (the chosen one highlighted) and Cancel and Confirm.
///
/// A local `Text` (`Text::Text`, 0); the club = parameter 0 in the club table; no manager (`club::MANAGER`): the Text
/// destroyed and nothing else. The chosen request = parameter 1 (byte); parameter 2 read and not used. The club's
/// background (`background_set_club_picture`, 0, 0); the title: the manager's name (500 bytes) in the club's kit
/// colours; the subtitle "Meet with the Football Association"; the rows = 0x195 / font 3's height (signed, a byte);
/// a 7-column area (weights 2,20,2,10,2,4,3) from (0x6e,0x8c) to (0x30c,0x221) where the explanation ("Specify the
/// details of requests from the Football Association:", translated) is wrapped (`Text::set_string`,
/// `Text::draw_wrapped`, font 3, from line 0); then a 2-column area (weights 2,17) over the same rectangle and, from the
/// line after the explanation + 2, the requests 1 and 2 (`get_fa_request_option_text` 0x6a9e20, 2000 bytes) as buttons
/// in column 1 (id 100, value the request), in the highlight colour [0xaebdec] when chosen, otherwise [0xae317e];
/// the first button's item goes to parameter 2. The menu bar (4, 0); a 2-column area (weights 3/1) in the kit's second
/// colour with "Cancel" (id 4) and "Confirm" (id 5); the Text destroyed.
/// Original: `fa_meeting_screen_draw` (0x58ad30, fifa_confed.cpp, cdecl).
pub(crate) unsafe extern "C" fn fa_meeting_screen_draw() {
    type DrawWrapped = unsafe extern "thiscall" fn(*mut usize, u32, u32, u32, *mut i32, u32, u32, u32, u32) -> u32;
    type RequestText = unsafe extern "thiscall" fn(usize, u32, usize, u32);
    let weights_explanation: [u8; 7] = [2, 0x14, 2, 0xa, 2, 4, 3];
    let weights_requests: [u8; 2] = [2, 0x11];
    let weights_buttons: [u8; 2] = [3, 1];
    let mut text = [0usize; 8];
    let mut name = [0u8; 500];
    // the wrapped text's line counter (zeroed again by the original just before the wrap)
    let mut line: i32 = 0;
    exe::new_text(text.as_mut_ptr(), 0usize);
    let club = club_at(get_screen_param(0) as i32 as isize);
    let manager = club.manager().addr();
    if manager == 0 {
        exe::drop_text(text.as_mut_ptr());
        return;
    }
    covered!("tel34_5 fa meeting");
    let chosen = get_screen_param(1) as u8;
    get_screen_param(2);
    exe::background_set_club_picture(club, 0, 0);
    let (mut fore, mut back) = (0u32, 0u32);
    exe::database_get_club_kit_colours(club, 1, &mut fore, &mut back);
    exe::database_format_staff_name(manager, name.as_mut_ptr() as usize, 0x1f4, 1);
    exe::screenmanager_add_screen_title(G_SCREEN_MANAGER, back, fore, name.as_ptr() as usize);
    tel34_lang_text(0x9c7450); // "Meet with the Football Association"
    exe::screenmanager_add_screen_subtitle(G_SCREEN_MANAGER, JOB_TEXT, 1);
    let rows = 0x195i32.wrapping_div(exe::font_get_height(3)) as u8 as u32;
    let explanation = tel26_add_area(current_human_display(), [0x6e, 0x8c, 0x30c, 0x221, 7, weights_explanation.as_ptr() as u32, rows, 0, 2, 0, u32::MAX]);
    tel34_lang_text(0x9c740c); // "  Specify the details of requests from the Football Association:"
    exe::text_set_string(text.as_mut_ptr() as usize, JOB_TEXT as *const u8);
    let wrap: DrawWrapped = core::mem::transmute(FN_TEXT_DRAW_WRAPPED);
    wrap(text.as_mut_ptr(), explanation, 0x6e, 0x30c, &mut line, 3, job_colour(JOB_COLOUR_3184), 0, 0);
    let requests = tel26_add_area(current_human_display(), [0x6e, 0x8c, 0x30c, 0x221, 2, weights_requests.as_ptr() as u32, rows, 0, 1, 0, u32::MAX]);
    line = line.wrapping_add(2);
    let request_text: RequestText = core::mem::transmute(FN_GET_FA_REQUEST_OPTION_TEXT);
    for request in 1u8..=2 {
        request_text(read_usize(0xb67a44), request as u32, JOB_TEXT, 0x7d0);
        let colour = if chosen == request { job_colour(JOB_COLOUR_BDEC) } else { job_colour(JOB_COLOUR_317E) };
        let item = tel26_area_button([requests, 1, line as u32, 1, 0, 1, 3, colour, JOB_TEXT as u32, 0x64, request as i8 as i32 as u32]);
        if request == 1 {
            set_screen_param(2, item as u16 as i16 as isize as usize);
        }
        line = line.wrapping_add(1);
    }
    exe::menubar_build(4, 0);
    let buttons = tel26_add_area(current_human_display(), [0x64, 0x22b, 0x316, 0x24e, 2, weights_buttons.as_ptr() as u32, 1, 0, 1, back, u32::MAX]);
    tel34_lang_text(0x98a1a0); // "Cancel"
    tel26_area_button([buttons, 0, 0, 0x30, job_colour(JOB_COLOUR_317E), 0xc, 3, job_colour(JOB_COLOUR_3184), JOB_TEXT as u32, 4, 0]);
    tel34_lang_text(0x98a198); // "Confirm"
    tel26_area_button([buttons, 1, 0, 0x30, job_colour(JOB_COLOUR_317E), 0xc, 3, job_colour(JOB_COLOUR_3184), JOB_TEXT as u32, 5, 0]);
    exe::drop_text(text.as_mut_ptr());
}

/// Rule: on the FA meeting screen a request button picks that request (the two buttons recoloured, the screen
/// redrawn); Confirm sends the chosen request to the FA and closes; Cancel closes; other widgets go to the menu bar.
///
/// The club = parameter 0 in the club table, the chosen request = parameter 1 (parameter 2 read and not used). With
/// the dialog flag (0xb77c84) set: the pending command argument cleared and -9. Id 100: the button's value (0 for -1),
/// parameter 2 = the first button's item; value 1: the first button in the highlight colour [0xaebdec] and the second in
/// [0xae317e]; value 2: the other way round (`ScreenManager::set_widget_text_colour`); any value: parameter 1 = it,
/// `ScreenManager::redraw_screen` (0, 0), 0. Id 5: with a chosen request, `MANAGER_MANAGER::handle_fa_request`
/// (0x6a9e60, club, request); -9. Id 4: -9.
/// Original: `fa_meeting_screen_handle_event` (0x58b0f0, fifa_confed.cpp, cdecl).
pub(crate) unsafe extern "C" fn fa_meeting_screen_handle_event(raw: u32) -> i32 {
    let club = club_at(get_screen_param(0) as i32 as isize);
    let chosen = get_screen_param(1);
    get_screen_param(2);
    if read_u32(TEL34_SCREEN_DIALOG_FLAG) != 0 {
        write_u32(G_PENDING_COMMAND_ARG, 0);
        return -9;
    }
    let item = raw as i16;
    match tel26_item_id(item) {
        100 => {
            covered!("tel34_5 fa meeting pick");
            let value = tel26_item_value(item);
            let first = get_screen_param(2) as u32;
            let colour = |widget: u32, c: usize| exe::screenmanager_set_widget_text_colour(G_SCREEN_MANAGER, widget, job_colour(c));
            match value {
                1 => {
                    colour(first, JOB_COLOUR_BDEC);
                    colour(first.wrapping_add(1), JOB_COLOUR_317E);
                }
                2 => {
                    colour(first, JOB_COLOUR_317E);
                    colour(first.wrapping_add(1), JOB_COLOUR_BDEC);
                }
                _ => {}
            }
            set_screen_param(1, value as usize);
            exe::screenmanager_redraw_screen(G_SCREEN_MANAGER, 0, 0);
            0
        }
        5 => {
            if chosen != 0 {
                covered!("tel34_5 fa meeting confirm");
                exe::manager_manager_handle_fa_request(read_usize(0xb67a44), club.addr(), chosen as u32);
            }
            -9
        }
        4 => -9,
        _ => {
            let r = exe::menubar_handle_command(raw);
            if r != 0 { r } else { exe::menubar_handle_object_link(raw) }
        }
    }
}

/// Comparer for `fa_meeting_open_screen`.
pub(crate) unsafe extern "C" fn compare_fa_meeting_open_screen(club: usize) {
    // simplification: opening a screen does not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn(usize)>(IDX_FA_MEETING_OPEN_SCREEN)(club)
}

/// Comparer for `fa_meeting_screen_draw`: the FA meeting screen side by side over the display list.
pub(crate) unsafe extern "C" fn compare_fa_meeting_screen_draw() {
    let o = original_fn::<unsafe extern "C" fn()>(IDX_FA_MEETING_SCREEN_DRAW);
    compare_by_display_list_with("FA meeting screen (fa_meeting_screen_draw)", &[], || o(), || fa_meeting_screen_draw());
}

/// Comparer for `fa_meeting_screen_handle_event`.
pub(crate) unsafe extern "C" fn compare_fa_meeting_screen_handle_event(raw: u32) -> i32 {
    // simplification: the redraw (network), the FA request and the menu bar commands do not run twice; proven in Rust
    // mode
    original_fn::<unsafe extern "C" fn(u32) -> i32>(IDX_FA_MEETING_SCREEN_HANDLE_EVENT)(raw)
}

// ---------- batch 318: the Search For screen and the friendly teams' other clubs input (find_screens.cpp) ----------

/// The search engine of a Search For tab (`SearchEngine`, 0x3c bytes): the found records (+0x34, an array of record
/// pointers) and their count (+0x38).
const SEARCH_ENGINE_SIZE: u32 = 0x3c;
const SEARCH_ENGINE_RESULTS: usize = 0x34;
const SEARCH_ENGINE_COUNT: usize = 0x38;
/// A continent record: its name (+4) and its federation's name (+0xa3), as the nations tab shows them [inference].
const CONTINENT_NAME: usize = 0x4;
const CONTINENT_FEDERATION_NAME: usize = 0xa3;
/// A tab bar entry (`MenuItem`, 0xd4 bytes): the text at +4, the kind at +0xcc and the value at +0xd0.
const FIND_TAB_ENTRY_SIZE: usize = 0xd4;
/// The size of a competition record of `G_CLUB_COMP_TABLE` (107 bytes).
const FIND_COMP_RECORD_SIZE: usize = 0x6b;

/// One of the four tabs of the Search For screen: its first parameter (`base`: the search text is `base` + 1, the
/// search engine + 2, the "search again" flag + 3, the first row shown + 4, the scroll row + 5, the list area + 6), the
/// edit box's kind and id, the search (`SearchEngine::find_clubs` 0x804fe0 or `find_staff` 0x805310) and its mode, and
/// the headings "<things> Matching ..." and "All <things>".
struct Tel34FindTab {
    base: u32,
    edit_kind: u32,
    edit_id: u32,
    search: usize,
    mode: u32,
    matching: usize,
    all: usize,
}

const FIND_NATIONS: Tel34FindTab = Tel34FindTab { base: 0, edit_kind: 0x880018, edit_id: 6, search: 0x804fe0, mode: 1, matching: 0x9ca0c8, all: 0x9ca0bc };
const FIND_CLUBS: Tel34FindTab = Tel34FindTab { base: 6, edit_kind: 0x480018, edit_id: 7, search: 0x804fe0, mode: 0, matching: 0x9ca12c, all: 0x9ca120 };
const FIND_NON_PLAYERS: Tel34FindTab = Tel34FindTab { base: 0xc, edit_kind: 0x2380018, edit_id: 8, search: 0x805310, mode: 1, matching: 0x9ca174, all: 0x9ca164 };
const FIND_PLAYERS: Tel34FindTab = Tel34FindTab { base: 0x12, edit_kind: 0x1380018, edit_id: 9, search: 0x805310, mode: 0, matching: 0x9ca1ac, all: 0x9ca1a0 };

/// `ScreenManager::add_text_item` (0x803fd0, thiscall, ret 0x2c): x1, y1, x2, y2, the style, the colour, the text
/// flags, the font, the text colour, the text and an unused dword.
unsafe fn tel34_text_item(f: [u32; 11]) -> u32 {
    type TextItem = unsafe extern "thiscall" fn(usize, u32, u32, u32, u32, u32, u32, u32, u32, u32, u32, u32) -> u32;
    let g: TextItem = core::mem::transmute(FN_SCREENMANAGER_ADD_TEXT_ITEM);
    g(G_SCREEN_MANAGER, f[0], f[1], f[2], f[3], f[4], f[5], f[6], f[7], f[8], f[9], f[10])
}

/// A cell of a result row in the list area: `add_area_text` in column `column` of row `row`, the result style
/// (1, 0, 1, 2) in the colour word at `colour`.
unsafe fn tel34_find_cell_text(area: u32, column: u32, row: u32, colour: usize, text: usize) {
    tel26_area_text([area, column, row, 1, 0, 1, 2, job_colour(colour), text as u32]);
}

/// A linked cell of a result row: `add_area_button` in column `column` of row `row` (style 1, 0, 1, `font`) with the
/// link id and object.
unsafe fn tel34_find_cell_link(area: u32, column: u32, row: u32, font: u32, colour: u32, text: usize, id: u32, object: usize) {
    tel26_area_button([area, column, row, 1, 0, 1, font, colour, text as u32, id, object as u32]);
}

/// The common body of the four result tabs (the routine's whole frame but the rows): the parameters, the search
/// engine, the "Search For" edit box, the search when asked, the page buttons, the heading, the list area and, for
/// each record shown, `row(area, row, record)`; then the scroll row and the area kept.
///
/// The search text = parameter `base` + 1 and the engine = + 2; parameter 0x19 is read and cleared. No engine yet:
/// one is made (`operator new` 0x3c bytes and `SearchEngine::SearchEngine`, or 0 when the allocation fails), kept in
/// + 2, and the "search again" flag + 3 set. The first row shown = + 4. An area from (0x6e, `top`) to (0x168, `top` +
/// 0x14) with "Search For" and the edit box (the tab's kind, the text at most 0x19 chars, the tab's id). With the flag:
/// the search (the text, the tab's mode) and the flag cleared. More than 100 found: the page buttons
/// (`gui_add_page_buttons`: right edge 0x30c at `top`, the page = first / 16 + 1, the pages = found / 16 rounded up,
/// ids 2..5) and at most 16 rows. The heading at `top` + 0x19: "<things> Matching <text>" or, with an empty text, "All
/// <things>". The list area from `top` + 0x41 to `bottom` (3 columns, weights 3/2/2, as many rows as fit in font 3 with
/// 16 pixels to spare), the rows from the first shown; the area scrolled to + 5, + 6 = the area.
unsafe fn tel34_find_results(tab: &Tel34FindTab, top: i32, bottom: i32, mut row: impl FnMut(u32, u32, usize)) {
    let weights: [u8; 3] = [3, 2, 2];
    let text = get_screen_param(tab.base + 1);
    let mut engine = get_screen_param(tab.base + 2);
    get_screen_param(0x19);
    set_screen_param(0x19, 0);
    if engine == 0 {
        let memory = exe::crt_operator_new(SEARCH_ENGINE_SIZE);
        engine = if memory != 0 {
            exe::new_searchengine(memory)
        } else {
            0
        };
        set_screen_param(tab.base + 2, engine);
        set_screen_param(tab.base + 3, 1);
    }
    let start = get_screen_param(tab.base + 4) as i32;
    let edit_area = tel26_add_area(current_human_display(), [0x6e, top as u32, 0x168, top.wrapping_add(0x14) as u32, 2, 0, 1, 0, 1, 0, u32::MAX]);
    tel34_lang_text(0x9ca0f0); // "Search For"
    tel26_area_text([edit_area, 0, 0, 2, 0, 0xc, 1, job_colour(JOB_COLOUR_3184), JOB_TEXT as u32]);
    tel26_add_item(current_human_display(), [tab.edit_kind, 0, 0, 0, 0, 1, 0, 2, 0, 0, 0xc, 1, job_colour(JOB_COLOUR_BDE8), text as u32, 0x19,
        tab.edit_id, 0, edit_area]);
    if get_screen_param(tab.base + 3) != 0 {
        covered!("tel34_6 search");
        let search: unsafe extern "thiscall" fn(usize, usize, u32) = core::mem::transmute(tab.search);
        search(engine, text, tab.mode);
        set_screen_param(tab.base + 3, 0);
    }
    let count = read_i32(engine + SEARCH_ENGINE_COUNT);
    let paged = count > 100;
    if paged {
        covered!("tel34_6 page buttons");
        type PageButtons = unsafe extern "C" fn(i32, i32, i32, i32, u32, u32, u32, u32) -> i32;
        let pages: PageButtons = core::mem::transmute(FN_GUI_ADD_PAGE_BUTTONS);
        pages(0x30c, top, start / 16 + 1, count / 16 + (count % 16 != 0) as i32, 2, 3, 4, 5);
    }
    let lang: Tel34FormatFn = core::mem::transmute(FN_LANGLIB_SPRINTF);
    if read_u8(text) != 0 {
        lang(JOB_TEXT, tab.matching, text);
    } else {
        lang(JOB_TEXT, tab.all);
    }
    let heading = top.wrapping_add(0x19);
    tel34_text_item([0x6e, heading as u32, 0x30c, heading.wrapping_add(0x23) as u32, 2, 0, 0xc, 3, job_colour(JOB_COLOUR_BDEC), JOB_TEXT as u32, 0]);
    let list_top = top.wrapping_add(0x41);
    let rows = (bottom.wrapping_sub(list_top).wrapping_sub(0x10) / exe::font_get_height(3)) as u8;
    let area = tel26_add_area(current_human_display(), [0x6e, list_top as u32, 0x30c, bottom as u32, 3, weights.as_ptr() as u32, rows as u32, 0, 2, 0, u32::MAX]);
    let results = read_usize(engine + SEARCH_ENGINE_RESULTS);
    let mut k: i32 = 0;
    while start.wrapping_add(k) < read_i32(engine + SEARCH_ENGINE_COUNT) {
        if paged && k >= 16 {
            break;
        }
        let record = read_usize(results.wrapping_add((start.wrapping_add(k) as usize).wrapping_mul(4)));
        row(area, k as u32, record);
        k += 1;
    }
    let scroll = get_screen_param(tab.base + 5);
    if area as i16 != -1 {
        exe::area_set_scroll_row(display_area_at(current_human_display(), area as i16), scroll);
    }
    set_screen_param(tab.base + 6, area as i16 as isize as usize);
}

/// The first cell of a club result row: the club's short name ("  %s") linked to the club (id 0x7d5) in the
/// highlight colour when a human manages it (`human_manager_is_human_club`, 0, 1, 0, 0), otherwise in the text colour.
unsafe fn tel34_find_club_name(area: u32, row: u32, club: usize) {
    let club = Club(club);
    let crt: Tel34FormatFn = core::mem::transmute(FN_CRT_SPRINTF);
    let human = exe::human_manager_is_human_club(club, 0, 1, 0, 0) != 0;
    crt(JOB_TEXT, 0x987ff0, club.addr() + club::SHORT_NAME); // "  %s"
    let colour = if human { job_colour(JOB_COLOUR_BDEC) } else { job_colour(JOB_COLOUR_3184) };
    tel34_find_cell_link(area, 0, row, 3, colour, JOB_TEXT, 0x7d5, club.addr());
}

/// The division cell (column 2) of a club: the division's short name linked to it (id 2000) when the competition is
/// loaded (an object in [`G_COMP_OBJECT_TABLE`]), as plain text otherwise; "Unknown Division" without one. With
/// `lower_division`, a division whose nation's league is selected (`nation::LEAGUE_SELECTED`) but not loaded shows "A
/// lower division" (`KEY_CLUB_COMP_A_LOWER_DIVISION`'s short name).
unsafe fn tel34_find_division_cell(area: u32, row: u32, club: usize, lower_division: bool) {
    let club = Club(club);
    let division = club.division().addr();
    if division == 0 {
        tel34_lang_text(0x9ca0fc); // "Unknown Division"
        tel34_find_cell_text(area, 2, row, JOB_COLOUR_BDD4, JOB_TEXT);
        return;
    }
    let loaded = read_usize(read_usize(G_COMP_OBJECT_TABLE).wrapping_add((read_u32(division) as usize).wrapping_mul(4))) != 0;
    if lower_division {
        let nation = Nation(read_usize(division + competition::NATION));
        if !nation.is_null() && nation.league_selected() != 0 && !loaded {
            let generic = read_usize(G_CLUB_COMP_TABLE).wrapping_add((read_i32(KEY_CLUB_COMP_A_LOWER_DIVISION) as usize).wrapping_mul(FIND_COMP_RECORD_SIZE));
            tel34_find_cell_text(area, 2, row, JOB_COLOUR_BDD4, generic + competition::SHORT_NAME);
            return;
        }
    }
    if loaded {
        tel34_find_cell_link(area, 2, row, 2, job_colour(JOB_COLOUR_BDD4), division + competition::SHORT_NAME, 2000, division);
    } else {
        tel34_find_cell_text(area, 2, row, JOB_COLOUR_BDD4, division + competition::SHORT_NAME);
    }
}

/// A staff result row: the person's name ("  %s", `database_format_staff_name` 2000 bytes, style 3) linked to him
/// (id 0x7d7), highlighted when his club is a human's; then his club's short name linked to it (id 0x7d5) and its
/// division (`tel34_find_division_cell`), or "No Club" and "No Division".
unsafe fn tel34_find_staff_row(area: u32, row: u32, person: usize, club: usize) {
    let club = Club(club);
    let crt: Tel34FormatFn = core::mem::transmute(FN_CRT_SPRINTF);
    let mut name = [0u8; 0x7d0];
    let human = !club.is_null() && exe::human_manager_is_human_club(club, 0, 1, 0, 0) != 0;
    exe::database_format_staff_name(person, name.as_mut_ptr() as usize, 0x7d0, 3);
    crt(JOB_TEXT, 0x987ff0, name.as_ptr()); // "  %s"
    let colour = if human { job_colour(JOB_COLOUR_BDEC) } else { job_colour(JOB_COLOUR_3184) };
    tel34_find_cell_link(area, 0, row, 3, colour, JOB_TEXT, 0x7d7, person);
    if club.is_null() {
        tel34_lang_text(0x9ca15c); // "No Club"
        tel34_find_cell_text(area, 1, row, JOB_COLOUR_BDEC, JOB_TEXT);
        tel34_lang_text(0x9ca150); // "No Division"
        tel34_find_cell_text(area, 2, row, JOB_COLOUR_BDD4, JOB_TEXT);
        return;
    }
    tel34_find_cell_link(area, 1, row, 2, job_colour(JOB_COLOUR_BDEC), club.addr() + club::SHORT_NAME, 0x7d5, club.addr());
    tel34_find_division_cell(area, row, club.addr(), false);
}

/// Rule: a click on the Other clubs tab of Choose Friendly Teams keeps the list's scroll row and, on a club (id 7)
/// other than the one kept, keeps it (-11, rebuild); otherwise 0.
///
/// For an item (not -1) parameter 0x11 = the scroll row of the area in parameter 0x12. Id 7 (or the command id): the
/// item's value (0 for -1) against parameter 0x10; different: parameter 0x10 = it, -11.
/// Original: `choose_friendly_teams_other_clubs_input` (0x5a2b30, find_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn choose_friendly_teams_other_clubs_input(raw: u32) -> i32 {
    let item = raw as i16;
    if item != -1 {
        let row = exe::screenmanager_get_area_scroll_row(G_SCREEN_MANAGER, get_screen_param(0x12));
        set_screen_param(0x11, row);
    }
    if tel26_item_id(item) == 7 && tel26_item_value(item) as usize != get_screen_param(0x10) {
        covered!("tel34_6 friendly other club");
        set_screen_param(0x10, tel26_item_value(item) as usize);
        return -11;
    }
    0
}

/// Rule: opening the Search For screen on a tab (1 nations, 2 clubs, 3 non-players, 4 players) with every tab reset.
///
/// `open_screen` (builder 0x5a2e60, input 0x5a45c0, flag 0, leave `release_find_screen` 0x5a4eb0, no exit); when it
/// opens, parameter 0 = the tab (signed byte) and, for each tab's parameters (1, 7, 0xd, 0x13 onward): the search text
/// = a copy of 25 spaces (`set_screen_param` with copy) emptied at once (its first byte 0), no engine, "search again"
/// 1, first row, scroll and area 0; then parameter 0x19 = 1.
/// Original: `open_find_screen` (0x5a2c30, find_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn open_find_screen(tab: u32) {
    if exe::screenmanager_open_screen(G_SCREEN_MANAGER, 0x5a2e60usize, 0x5a45c0usize, 0, 0x5a4eb0usize, 0) == 0 {
        return;
    }
    covered!("tel34_6 open find screen");
    set_screen_param(0, tab as u8 as i8 as isize as usize);
    let mut spaces = [0x20u8; 26];
    spaces[25] = 0;
    for base in [0u32, 6, 0xc, 0x12] {
        exe::screenmanager_set_screen_param(G_SCREEN_MANAGER, base + 1, spaces.as_ptr() as usize, 1);
        write_u8(get_screen_param(base + 1), 0);
        set_screen_param(base + 2, 0);
        set_screen_param(base + 3, 1);
        set_screen_param(base + 4, 0);
        set_screen_param(base + 5, 0);
        set_screen_param(base + 6, 0);
    }
    set_screen_param(0x19, 1);
}

/// Rule: building the Search For screen: the title, the menu bar, the four tabs and the open tab's results.
///
/// 25 tab entries (`MenuItem`: word +0 = -1, word +2 = 0; the other bytes are stack leftovers in the original, zero
/// here); the tab = parameter 0 (byte); the game title (heading colours 0 and 1); the menu bar (4, 0); the entries
/// "Nation", "Club", "Non-Player" and "Player" (translated, kind 1, value 1..4); the tab bar (`gui_add_tab_bar`, 4
/// entries, from 0x50 to 0x221, split). Tab 1: the nation background (null) and the nations; 2: the club background
/// (null) and the clubs; 3 and 4: the staff background (null) and the non-players or players (the four result routines
/// called by their addresses, as the original); any other: a random background and an empty area (0x6e, top .. 0x30c,
/// bottom). Then the Back/Next buttons.
/// Original: `draw_find_screen` (0x5a2e60, find_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn draw_find_screen() {
    let mut entries = [[0u8; FIND_TAB_ENTRY_SIZE]; 0x19];
    for e in entries.iter_mut() {
        e[0] = 0xff;
        e[1] = 0xff;
    }
    covered!("tel34_6 find screen");
    let tab = get_screen_param(0) as u8 as i8;
    tel34_game_title();
    exe::menubar_build(4, 0);
    let lang: Tel34FormatFn = core::mem::transmute(FN_LANGLIB_SPRINTF);
    for (k, text) in [0x9ca010usize, 0x9ca08c, 0x9ca080, 0x9ca078].into_iter().enumerate() {
        // "Nation", "Club", "Non-Player", "Player"
        lang(entries[k][4..].as_mut_ptr() as usize, text);
        entries[k][0xcc..0xd0].copy_from_slice(&1u32.to_le_bytes());
        entries[k][0xd0..0xd4].copy_from_slice(&(k as u32 + 1).to_le_bytes());
    }
    let (mut top, mut bottom) = (0x50i32, 0x221i32);
    exe::gui_add_tab_bar(entries.as_mut_ptr() as usize, 4, tab as i32, &mut top, &mut bottom, 1);
    let picture = |address: usize| {
        let f: unsafe extern "C" fn(usize, u32, u32) -> u32 = core::mem::transmute(address);
        f(0, 0, 0);
    };
    // the result tabs by their exe addresses: the 1080 exe has its own (27 rows per page), left unhooked there
    let results = |address: usize| {
        let f: unsafe extern "C" fn(i32, i32) = core::mem::transmute(address);
        f(top, bottom);
    };
    match tab {
        1 => {
            picture(0x41c100);
            results(0x5a30f0);
        }
        2 => {
            picture(0x41c250);
            results(0x5a35b0);
        }
        3 => {
            picture(0x41c790);
            results(0x5a3af0);
        }
        4 => {
            picture(0x41c790);
            results(0x5a4060);
        }
        _ => {
            exe::background_set_random_picture();
            tel26_add_area(current_human_display(), [0x6e, top as u32, 0x30c, bottom as u32, 1, 0, 1, 0, 2, 0, u32::MAX]);
        }
    }
    tel26_back_next();
}

/// Rule: the nations tab of the Search For screen: the national teams found (`SearchEngine::find_clubs` with national
/// teams), each with its continent and federation.
///
/// `tel34_find_results` with the nations tab; each row: the team (`tel34_find_club_name`), then, when its nation has a
/// continent (`nation::CONTINENT`), the continent's name (column 1, highlight colour) and its federation's (column 2),
/// otherwise "Unknown Continent" and "Unknown Federation".
/// Original: `draw_find_nations_results` (0x5a30f0, find_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn draw_find_nations_results(top: i32, bottom: i32) {
    covered!("tel34_6 nations");
    tel34_find_results(&FIND_NATIONS, top, bottom, |area, row, team| {
        tel34_find_club_name(area, row, team);
        let nation = Nation(read_usize(team + club::NATION));
        if !nation.is_null() && nation.continent() != 0 {
            let continent = nation.continent();
            tel34_find_cell_text(area, 1, row, JOB_COLOUR_BDEC, continent + CONTINENT_NAME);
            tel34_find_cell_text(area, 2, row, JOB_COLOUR_BDD4, continent + CONTINENT_FEDERATION_NAME);
        } else {
            tel34_lang_text(0x9ca0a8); // "Unknown Continent"
            tel34_find_cell_text(area, 1, row, JOB_COLOUR_BDEC, JOB_TEXT);
            tel34_lang_text(0x9ca094); // "Unknown Federation"
            tel34_find_cell_text(area, 2, row, JOB_COLOUR_BDD4, JOB_TEXT);
        }
    });
}

/// Rule: the clubs tab of the Search For screen: the clubs found, each with its nation and its division.
///
/// `tel34_find_results` with the clubs tab; each row: the club (`tel34_find_club_name`), its nation's name linked to
/// the nation's national team (id 0x7d5, `database_get_national_team`) or "Unknown Nation", and its division
/// (`tel34_find_division_cell` with "A lower division").
/// Original: `draw_find_clubs_results` (0x5a35b0, find_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn draw_find_clubs_results(top: i32, bottom: i32) {
    covered!("tel34_6 clubs");
    tel34_find_results(&FIND_CLUBS, top, bottom, |area, row, club| {
        tel34_find_club_name(area, row, club);
        let nation = read_usize(club + club::NATION);
        if nation != 0 {
            let team = exe::database_get_national_team(nation);
            tel34_find_cell_link(area, 1, row, 2, job_colour(JOB_COLOUR_BDEC), nation + 4, 0x7d5, team);
        } else {
            tel34_lang_text(0x9ca110); // "Unknown Nation"
            tel34_find_cell_text(area, 1, row, JOB_COLOUR_BDEC, JOB_TEXT);
        }
        tel34_find_division_cell(area, row, club, true);
    });
}

/// Rule: the non-players tab of the Search For screen: the staff found (`SearchEngine::find_staff`, non-players), each
/// with his club and its division.
///
/// `tel34_find_results` with the non-players tab; the club shown = his national job (`staff::NATIONAL_JOB`) when he
/// has one with `staff::JOB_FOR_NATION` 5 and `staff::JOB_FOR_CLUB` not 5, otherwise his club (`staff::CLUB_JOB`);
/// the row is `tel34_find_staff_row`.
/// Original: `draw_find_non_players_results` (0x5a3af0, find_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn draw_find_non_players_results(top: i32, bottom: i32) {
    covered!("tel34_6 non-players");
    tel34_find_results(&FIND_NON_PLAYERS, top, bottom, |area, row, person| {
        let national = read_usize(person + staff::NATIONAL_JOB);
        let club = if national != 0 && read_u8(person + staff::JOB_FOR_NATION) == 5 && read_u8(person + staff::JOB_FOR_CLUB) != 5 {
            national
        } else {
            read_usize(person + staff::CLUB_JOB)
        };
        tel34_find_staff_row(area, row, person, club);
    });
}

/// Rule: the players tab of the Search For screen: the players found (`SearchEngine::find_staff`, players), each with
/// his club (`staff::CLUB_JOB`) and its division (`tel34_find_staff_row`).
/// Original: `draw_find_players_results` (0x5a4060, find_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn draw_find_players_results(top: i32, bottom: i32) {
    covered!("tel34_6 players");
    tel34_find_results(&FIND_PLAYERS, top, bottom, |area, row, person| {
        tel34_find_staff_row(area, row, person, read_usize(person + staff::CLUB_JOB));
    });
}

/// The input of a result tab: for an item (not -1) the scroll row (+ 5) = the area's (+ 6); the tab's edit box id
/// (search) sets "search again" (+ 3) and clears the first row (+ 4) and the scroll (+ 5); the page ids move the first
/// row (+ 4): 2 back 160, 3 back 16 (below 0: up to the first page boundary at or above 0), 4 on 16, 5 on 160 (past
/// the last found: back by whole pages of 16 until it is at or before it). Each answers -11; anything else 0.
unsafe fn tel34_find_tab_input(raw: u32, base: u32, edit_id: u16) -> i32 {
    let engine = get_screen_param(base + 2);
    let start = get_screen_param(base + 4) as i32;
    let item = raw as i16;
    if item != -1 {
        let row = exe::screenmanager_get_area_scroll_row(G_SCREEN_MANAGER, get_screen_param(base + 6));
        set_screen_param(base + 5, row);
    }
    let id = tel26_item_id(item);
    if id == edit_id {
        covered!("tel34_6 search again");
        set_screen_param(base + 3, 1);
        set_screen_param(base + 4, 0);
        set_screen_param(base + 5, 0);
        return -11;
    }
    let back = |s: i32| if s < 0 { s.wrapping_add((0xfu32.wrapping_sub(s as u32) >> 4 << 4) as i32) } else { s };
    let on = |s: i32| {
        let last = read_i32(engine + SEARCH_ENGINE_COUNT).wrapping_sub(1);
        if s > last { s.wrapping_sub((s.wrapping_sub(last).wrapping_add(0xf) as u32 >> 4 << 4) as i32) } else { s }
    };
    let next = match id {
        2 => back(start.wrapping_sub(0xa0)),
        3 => back(start.wrapping_sub(0x10)),
        4 => on(start.wrapping_add(0x10)),
        5 => on(start.wrapping_add(0xa0)),
        _ => return 0,
    };
    covered!("tel34_6 page");
    set_screen_param(base + 4, next as usize);
    -11
}

/// Rule: a click on the Search For screen: the open tab's input first (search, pages), then a tab button (id 1) with
/// another tab opens it (-11); otherwise the menu bar.
///
/// The tab = parameter 0 (byte): 1 the nations' input (edit id 6), 2 the clubs' (7), 3 `find_screen_non_players_input`,
/// 4 `find_screen_players_input` (`tel34_find_tab_input`); an answer other than 0 is returned. Then id 1: the item's
/// value against parameter 0; different: parameter 0 = it, -11. Otherwise `menubar_handle_command`, then
/// `menubar_handle_object_link` when it gives 0.
/// Original: `find_screen_input` (0x5a45c0, find_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn find_screen_input(raw: u32) -> i32 {
    let r = match get_screen_param(0) as u8 as i8 {
        1 => tel34_find_tab_input(raw, FIND_NATIONS.base, 6),
        2 => tel34_find_tab_input(raw, FIND_CLUBS.base, 7),
        3 => find_screen_non_players_input(raw) as i32,
        4 => find_screen_players_input(raw) as i32,
        _ => 0,
    };
    if r != 0 {
        return r;
    }
    let item = raw as i16;
    if tel26_item_id(item) as i16 == 1 && tel26_item_value(item) as usize != get_screen_param(0) {
        covered!("tel34_6 change tab");
        set_screen_param(0, tel26_item_value(item) as usize);
        return -11;
    }
    let r = exe::menubar_handle_command(raw);
    if r != 0 { r } else { exe::menubar_handle_object_link(raw) }
}

/// Rule: the input of the non-players tab (parameters 0xd..0x12, edit id 8): `tel34_find_tab_input`.
/// Original: `find_screen_non_players_input` (0x5a4950, find_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn find_screen_non_players_input(raw: u32) -> u32 {
    tel34_find_tab_input(raw, FIND_NON_PLAYERS.base, 8) as u32
}

/// Rule: the input of the players tab (parameters 0x13..0x18, edit id 9): `tel34_find_tab_input`.
/// Original: `find_screen_players_input` (0x5a4c00, find_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn find_screen_players_input(raw: u32) -> u32 {
    tel34_find_tab_input(raw, FIND_PLAYERS.base, 9) as u32
}

/// Rule: leaving the Search For screen frees the four tabs' search engines (parameters 2, 8, 0xe and 0x14).
///
/// Each one set: `SearchEngine::~SearchEngine` (0x804fd0) and `operator delete`, and the parameter cleared.
/// Original: `release_find_screen` (0x5a4eb0, find_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn release_find_screen() {
    for k in [2u32, 8, 0xe, 0x14] {
        if get_screen_param(k) == 0 {
            continue;
        }
        let engine = get_screen_param(k);
        if engine != 0 {
            exe::drop_searchengine(engine);
            exe::crt_operator_delete(engine);
        }
        set_screen_param(k, 0);
    }
}

/// The parameters a find screen routine may write: the whole parameter block of the current screen (0x1a dwords).
unsafe fn tel34_find_params() -> [usize; 0x1a] {
    let mut p = [0usize; 0x1a];
    for (k, v) in p.iter_mut().enumerate() {
        *v = get_screen_param(k as u32);
    }
    p
}

/// Comparer for `choose_friendly_teams_other_clubs_input`: side by side over the screen parameters and the answer.
pub(crate) unsafe extern "C" fn compare_choose_friendly_teams_other_clubs_input(raw: u32) -> i32 {
    let o = original_fn::<unsafe extern "C" fn(u32) -> i32>(IDX_CHOOSE_FRIENDLY_TEAMS_OTHER_CLUBS_INPUT);
    let regions = screen_param_regions();
    let (ro, rr, equal, mo, mr) = crate::comparison::side_by_side(&regions, || o(raw), || choose_friendly_teams_other_clubs_input(raw));
    SCOREBOARD.record(equal && ro == rr, || format!("Choose Friendly Teams (choose_friendly_teams_other_clubs_input): answer {} x {}, differences in {:?}",
        ro, rr, first_differences(&mo, &mr)));
    ro
}

/// Comparer for `open_find_screen`.
pub(crate) unsafe extern "C" fn compare_open_find_screen(tab: u32) {
    // simplification: opening a screen does not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn(u32)>(IDX_OPEN_FIND_SCREEN)(tab)
}

/// Comparer for `draw_find_screen`: the Search For screen side by side over the display list, when every tab already
/// has its search engine and none has a search pending (a first build allocates the engine and searches: only the
/// original runs).
pub(crate) unsafe extern "C" fn compare_draw_find_screen() {
    let o = original_fn::<unsafe extern "C" fn()>(IDX_DRAW_FIND_SCREEN);
    let tab = get_screen_param(0) as u8 as i8;
    let base = match tab {
        1 => FIND_NATIONS.base,
        2 => FIND_CLUBS.base,
        3 => FIND_NON_PLAYERS.base,
        4 => FIND_PLAYERS.base,
        _ => return compare_by_display_list_with("Search For screen (draw_find_screen)", &[], || o(), || draw_find_screen()),
    };
    if get_screen_param(base + 2) == 0 || get_screen_param(base + 3) != 0 {
        // simplification: making the engine and searching do not run twice; proven in Rust mode
        return o();
    }
    compare_by_display_list_with("Search For screen (draw_find_screen)", &[], || o(), || draw_find_screen());
}

/// A result tab's comparer: side by side over the display list when the tab has its engine and no search pending;
/// otherwise only the original runs (allocation and search).
unsafe fn tel34_compare_find_results(tab: &Tel34FindTab, name: &str, original: impl FnOnce(), rust: impl FnOnce()) {
    if get_screen_param(tab.base + 2) == 0 || get_screen_param(tab.base + 3) != 0 {
        // simplification: making the engine and searching do not run twice; proven in Rust mode
        return original();
    }
    compare_by_display_list_with(name, &[], original, rust);
}

/// Comparer for `draw_find_nations_results`.
pub(crate) unsafe extern "C" fn compare_draw_find_nations_results(top: i32, bottom: i32) {
    let o = original_fn::<unsafe extern "C" fn(i32, i32)>(IDX_DRAW_FIND_NATIONS_RESULTS);
    tel34_compare_find_results(&FIND_NATIONS, "Search For screen (draw_find_nations_results)", || o(top, bottom), || draw_find_nations_results(top, bottom));
}

/// Comparer for `draw_find_clubs_results`.
pub(crate) unsafe extern "C" fn compare_draw_find_clubs_results(top: i32, bottom: i32) {
    let o = original_fn::<unsafe extern "C" fn(i32, i32)>(IDX_DRAW_FIND_CLUBS_RESULTS);
    tel34_compare_find_results(&FIND_CLUBS, "Search For screen (draw_find_clubs_results)", || o(top, bottom), || draw_find_clubs_results(top, bottom));
}

/// Comparer for `draw_find_non_players_results`.
pub(crate) unsafe extern "C" fn compare_draw_find_non_players_results(top: i32, bottom: i32) {
    let o = original_fn::<unsafe extern "C" fn(i32, i32)>(IDX_DRAW_FIND_NON_PLAYERS_RESULTS);
    tel34_compare_find_results(&FIND_NON_PLAYERS, "Search For screen (draw_find_non_players_results)", || o(top, bottom),
        || draw_find_non_players_results(top, bottom));
}

/// Comparer for `draw_find_players_results`.
pub(crate) unsafe extern "C" fn compare_draw_find_players_results(top: i32, bottom: i32) {
    let o = original_fn::<unsafe extern "C" fn(i32, i32)>(IDX_DRAW_FIND_PLAYERS_RESULTS);
    tel34_compare_find_results(&FIND_PLAYERS, "Search For screen (draw_find_players_results)", || o(top, bottom), || draw_find_players_results(top, bottom));
}

/// Comparer for `find_screen_input`.
pub(crate) unsafe extern "C" fn compare_find_screen_input(raw: u32) -> i32 {
    // simplification: the menu bar commands (they open screens) do not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn(u32) -> i32>(IDX_FIND_SCREEN_INPUT)(raw)
}

/// A tab input's comparer: side by side over the screen parameters and the answer.
unsafe fn tel34_compare_tab_input(name: &str, original: impl FnOnce() -> u32, rust: impl FnOnce() -> u32) -> u32 {
    let regions = screen_param_regions();
    let (ro, rr, equal, mo, mr) = crate::comparison::side_by_side(&regions, original, rust);
    SCOREBOARD.record(equal && ro == rr, || format!("Search For screen ({}): answer {} x {}, differences in {:?}", name, ro as i32, rr as i32,
        first_differences(&mo, &mr)));
    ro
}

/// Comparer for `find_screen_non_players_input`.
pub(crate) unsafe extern "C" fn compare_find_screen_non_players_input(raw: u32) -> u32 {
    let o = original_fn::<unsafe extern "C" fn(u32) -> u32>(IDX_FIND_SCREEN_NON_PLAYERS_INPUT);
    tel34_compare_tab_input("find_screen_non_players_input", || o(raw), || find_screen_non_players_input(raw))
}

/// Comparer for `find_screen_players_input`.
pub(crate) unsafe extern "C" fn compare_find_screen_players_input(raw: u32) -> u32 {
    let o = original_fn::<unsafe extern "C" fn(u32) -> u32>(IDX_FIND_SCREEN_PLAYERS_INPUT);
    tel34_compare_tab_input("find_screen_players_input", || o(raw), || find_screen_players_input(raw))
}

/// Comparer for `release_find_screen`: only the original runs (it frees the engines), the parameters checked against
/// the plan afterwards (2, 8, 0xe and 0x14 cleared, the others as they were).
pub(crate) unsafe extern "C" fn compare_release_find_screen() {
    let mut plan = tel34_find_params();
    for k in [2usize, 8, 0xe, 0x14] {
        plan[k] = 0;
    }
    original_fn::<unsafe extern "C" fn()>(IDX_RELEASE_FIND_SCREEN)();
    let got = tel34_find_params();
    SCOREBOARD.record(got == plan, || format!("Search For screen (release_find_screen): params {:x?} x plan {:x?}", got, plan));
}

// ---------- batch 318: the Discipline Player screen (Fine.cpp) ----------

/// The screen manager's network flag (`[0xb77c84]`): set, the screens of a network game answer every widget with -9.
const TEL35_NETWORK_FLAG: usize = 0xb77c84;
/// Fine.cpp's discipline texts: "Discipline Player", "Official Warning", "<%d - Fine period> Week Fine" and the
/// language-10 variants (a plain "%d" week text and a fixed one-week text).
const DISCIPLINE_TITLE: usize = 0x9cc0e8;
const DISCIPLINE_WARNING: usize = 0x9cc060;
const DISCIPLINE_WEEK_FINE: usize = 0x9cc01c;
const DISCIPLINE_WEEK_FINE_L10: usize = 0x9cc03c;
const DISCIPLINE_ONE_WEEK_L10: usize = 0x9cc050;

/// `Text::draw_wrapped(slot, left, right, &line, font, colour, style, flags)` (0x4aeaf0, thiscall, ret 0x20): lays a
/// Text's words out as area rows from `line` on, advancing it.
pub(crate) unsafe fn tel35_text_draw_wrapped(text: usize, area: u32, left: i32, right: i32, line: *mut i32, font: u32, colour: u32, style: u32, flags: u32) -> i32 {
    exe::text_draw_wrapped(text, area, left, right, line, font, colour, style, flags)
}

/// A colour word zero-extended (the original pushes a register with only its low half loaded).
pub(crate) unsafe fn tel35_colour(a: usize) -> u32 {
    read_u16(a) as u32
}

/// The person of screen parameter 0 (a staff id): the staff table entry.
unsafe fn discipline_person() -> usize {
    read_usize(G_STAFF_TABLE).wrapping_add((get_screen_param(0) as u32).wrapping_mul(staff::SIZE as u32) as usize)
}

/// The fine period's text into the screens' text buffer: 1 "Official Warning", otherwise "<n> Week Fine" with
/// n = period − 1 (langlib).
unsafe fn discipline_period_text(period: i32) {
    let text: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_LANGLIB_SPRINTF);
    if period == 1 {
        text(JOB_TEXT, DISCIPLINE_WARNING);
    } else {
        text(JOB_TEXT, DISCIPLINE_WEEK_FINE, period - 1);
    }
}

/// Rule: the Discipline Player screen opens for a person with the fine period at 1 (an official warning) and the reason
/// at 0.
///
/// `open_discipline_player_screen(&person)`: `open_screen` with the builder 0x5a83e0, the handler 0x5a8990, single
/// instance, the no-op leave routine 0x5a8f60 and 0; when it opens, parameter 0 = the person's id (the first dword of
/// the record the argument points to), 1 = 1 (the period) and 3 = 0 (the reason).
/// Original: `open_discipline_player_screen` (0x5a8380, Fine.cpp, cdecl).
pub(crate) unsafe extern "C" fn open_discipline_player_screen(person: usize) {
    covered!("tel35_1 open discipline");
    if exe::screenmanager_open_screen(G_SCREEN_MANAGER, 0x5a83e0usize, 0x5a8990usize, 1, 0x5a8f60usize, 0) == 0 {
        return;
    }
    set_screen_param(0, read_u32(person) as usize);
    set_screen_param(1, 1);
    set_screen_param(3, 0);
}

/// Rule: the Discipline Player screen shows the person's name in his club's colours, the sentence with a link to the
/// person, the period chooser ("-", the period, "+"; "-" greyed at a warning, "+" greyed at two weeks), the five
/// reasons (the chosen one in yellow) and Cancel / Confirm.
///
/// `draw_discipline_player_screen()`: the person of parameter 0 (`staff::SIZE` × id into the staff table); with no club
/// (`staff::CLUB_JOB`) nothing is built. Otherwise the period (parameter 1) and, as the reason, the low byte of
/// parameter 2 (the original reads 2, where this routine keeps the "-" widget, not 3 where the handler keeps the
/// reason: a defect kept). The person's background picture (`background_set_staff_picture`, 0, 0); the title: his name
/// (`database_format_staff_name`, 500 bytes, style 1) in the club's kit colours (kit 1); the subtitle "Discipline
/// Player". Area 1 (0x6e, 0x8c)-(0x30c, 0x221), seven columns (2, 20, 2, 10, 2, 4, 3), rows = 0x195 / the height of
/// font 3, kind 2: the sentence with the person's name (a Text with the link 0x7d7 to the person) drawn wrapped from
/// row 0 (font 3, pale grey); two rows below, "Disciplinary action:" (column 1), "-" in column 2 (a grey text at period
/// ≤ 1, otherwise a button id 2), its widget kept in parameter 2, the period's text in column 3 ("Official Warning", or
/// "<n> Week Fine"; in language 10 a fixed text for period 2 and a plain "%d" one otherwise), "+" in column 4 (a grey
/// text at period ≥ 3, otherwise a button id 1); two rows below "Reason For Disciplinary Action:". Area 2, the same
/// rectangle, two columns (2, 17), kind 1: from two rows below, the five reasons (`Fine::reason_text` k, 2000 bytes)
/// as buttons id 3 with data k, the chosen one yellow and the others grey. The menu bar (4, 0) and the button area
/// (0x64, 0x22b)-(0x316, 0x24e) (columns 3, 1; the club's background colour) with "Cancel" (id 4) and "Confirm" (id 5).
/// Original: `draw_discipline_player_screen` (0x5a83e0, Fine.cpp, cdecl).
pub(crate) unsafe extern "C" fn draw_discipline_player_screen() {
    let text: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_LANGLIB_SPRINTF);
    let format: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_CRT_SPRINTF);
    let columns: [u8; 7] = [2, 0x14, 2, 0xa, 2, 4, 3];
    let buttons: [u8; 4] = [3, 1, 2, 0x11];
    let mut tx = [0u32; 8];
    let t = tx.as_mut_ptr() as usize;
    exe::new_text(tx.as_mut_ptr() as *mut usize, 0usize);
    let person = Staff(discipline_person());
    let club = person.club_job().addr();
    if club == 0 {
        exe::drop_text(tx.as_mut_ptr() as *mut usize);
        return;
    }
    covered!("tel35_1 draw discipline");
    let period = get_screen_param(1) as u8 as i8 as i32;
    let reason = get_screen_param(2) as u8;
    exe::background_set_staff_picture(person.addr(), 0, 0);
    let (mut fore, mut back) = (0u32, 0u32);
    exe::database_get_club_kit_colours(club, 1, &mut fore, &mut back);
    let mut name = [0u8; 500];
    exe::database_format_staff_name(person, name.as_mut_ptr() as usize, 0x1f4, 1);
    exe::screenmanager_add_screen_title(G_SCREEN_MANAGER, back & 0xffff, fore & 0xffff, name.as_ptr() as usize);
    text(JOB_TEXT, DISCIPLINE_TITLE);
    exe::screenmanager_add_screen_subtitle(G_SCREEN_MANAGER, JOB_TEXT, 1);
    let rows = (0x195 / exe::font_get_height(3)) as u8 as u32;
    let d = current_human_display();
    let area = tel26_add_area(d, [0x6e, 0x8c, 0x30c, 0x221, 7, columns.as_ptr() as u32, rows, 0, 2, 0, u32::MAX]);
    text(JOB_TEXT, 0x9cc08c, 0x64, name.as_ptr());
    exe::text_set_string(t, JOB_TEXT as *const u8);
    exe::text_add_link(t, name.as_ptr(), 0x7d7, person);
    let mut line = 0i32;
    tel35_text_draw_wrapped(t, area, 0x6e, 0x30c, &mut line, 3, tel35_colour(G_GUI_COLOUR_PALE_GREY), 0, 0);
    let mut row = line + 2;
    let pale = tel35_colour(G_GUI_COLOUR_PALE_GREY);
    let grey = tel35_colour(G_GUI_COLOUR_GREY);
    let blue = tel35_colour(G_GUI_COLOUR_DARK_BLUE);
    text(JOB_TEXT, 0x9cc074);
    tel26_area_button([area, 1, row as u32, 1, 0, 1, 3, pale, JOB_TEXT as u32, 0, 0]);
    let minus = if period <= 1 {
        tel26_area_text([area, 2, row as u32, 0x30, blue, 0xc, 3, grey, 0x98ba0c])
    } else {
        tel26_area_button([area, 2, row as u32, 0x30, blue, 0xc, 3, pale, 0x98ba0c, 2, 0])
    };
    set_screen_param(2, minus as i16 as isize as usize);
    if period == 1 {
        text(JOB_TEXT, DISCIPLINE_WARNING);
    } else if exe::langlib_get_language() == 0xa {
        if period == 2 {
            tel26_copy_text(JOB_TEXT as *mut u8, DISCIPLINE_ONE_WEEK_L10 as *const u8);
        } else {
            format(JOB_TEXT, DISCIPLINE_WEEK_FINE_L10, period - 1);
        }
    } else {
        text(JOB_TEXT, DISCIPLINE_WEEK_FINE, period - 1);
    }
    tel26_area_text([area, 3, row as u32, 1, tel35_colour(G_GUI_COLOUR_BLACK), 0xc, 3, pale, JOB_TEXT as u32]);
    if period >= 3 {
        tel26_area_text([area, 4, row as u32, 0x30, blue, 0xc, 3, grey, 0x9afe7c]);
    } else {
        tel26_area_button([area, 4, row as u32, 0x30, blue, 0xc, 3, pale, 0x9afe7c, 1, 0]);
    }
    row += 2;
    text(JOB_TEXT, 0x9cbffc);
    tel26_area_button([area, 1, row as u32, 1, 0, 1, 3, pale, JOB_TEXT as u32, 0, 0]);
    row += 2;
    let reasons = tel26_add_area(d, [0x6e, 0x8c, 0x30c, 0x221, 2, buttons.as_ptr().wrapping_add(2) as u32, rows, 0, 1, 0, u32::MAX]);
    for k in 0..5u8 {
        exe::fine_reason_text(read_usize(G_FINE), k as u32, JOB_TEXT, 0x7d0, 0);
        let colour = if reason != k { grey } else { tel35_colour(G_GUI_COLOUR_YELLOW) };
        tel26_area_button([reasons, 1, row as u32, 1, 0, 1, 3, colour, JOB_TEXT as u32, 3, k as u32]);
        row += 1;
    }
    exe::menubar_build(4, 0);
    let d = current_human_display();
    let bar = tel26_add_area(d, [0x64, 0x22b, 0x316, 0x24e, 2, buttons.as_ptr() as u32, 1, 0, 1, back & 0xffff, u32::MAX]);
    text(JOB_TEXT, 0x98a1a0);
    tel26_area_button([bar, 0, 0, 0x30, grey, 0xc, 3, pale, JOB_TEXT as u32, 4, 0]);
    text(JOB_TEXT, 0x98a198);
    tel26_area_button([bar, 1, 0, 0x30, grey, 0xc, 3, pale, JOB_TEXT as u32, 5, 0]);
    exe::drop_text(tx.as_mut_ptr() as *mut usize);
}

/// Rule: on the Discipline Player screen "-" and "+" move the period between a warning and a two-week fine (greying
/// the button at the end), a reason click colours it yellow, Confirm fines the person and closes, Cancel closes.
///
/// `discipline_player_screen_input(item)`: in a network game (`[0xb77c84]`) the pending command argument is cleared and
/// -9 comes back. The widget's id (`tel26_item_id`): 2 ("-"): the period (parameter 1) goes down while above 1 and is
/// written back; the "-" widget (parameter 2) gets flags 6, grey and data 0 when the period reaches 1; the period text
/// (the next widget) is rewritten; "+" (the one after) gets flags 2, pale grey and id 1; redraw, 0. 1 ("+"): the period
/// goes up while below 3; "-" gets flags 2, pale grey and id 2; the text; "+" gets flags 6, grey and data 0 when it
/// reaches 3; redraw, 0. 3 (a reason): the widget's data k; the five reason widgets (parameter 2 + 4 ...) recoloured,
/// yellow the chosen one (k above 3 selects the fifth) and grey the others; parameter 3 = k; redraw, 0. 5 (Confirm):
/// `Fine::fine_player(person, period, reason)`, -9. 4 (Cancel): -9. Otherwise the menu bar's command, then its object
/// link.
/// Original: `discipline_player_screen_input` (0x5a8990, Fine.cpp, cdecl).
pub(crate) unsafe extern "C" fn discipline_player_screen_input(raw: u32) -> i32 {
    let person = discipline_person();
    let mut period = get_screen_param(1) as i32;
    let reason = get_screen_param(3);
    if read_u32(TEL35_NETWORK_FLAG) != 0 {
        write_u32(G_PENDING_COMMAND_ARG, 0);
        return -9;
    }
    let item = raw as i16;
    let sm = G_SCREEN_MANAGER;
    match tel26_item_id(item) {
        2 => {
            covered!("tel35_1 discipline minus");
            if period > 1 {
                period -= 1;
            }
            set_screen_param(1, period as usize);
            let mut w = get_screen_param(2) as u32;
            if period <= 1 {
                exe::screenmanager_set_widget_flags(sm, w as usize, 6);
                exe::screenmanager_set_widget_text_colour(sm, w, tel35_colour(G_GUI_COLOUR_GREY));
                exe::screenmanager_set_widget_data(sm, w, 0usize);
            }
            w = w.wrapping_add(1);
            discipline_period_text(period);
            exe::screenmanager_set_widget_text(sm, w, JOB_TEXT);
            w = w.wrapping_add(1);
            exe::screenmanager_set_widget_flags(sm, w as usize, 2);
            exe::screenmanager_set_widget_text_colour(sm, w, tel35_colour(G_GUI_COLOUR_PALE_GREY));
            exe::screenmanager_set_widget_id(sm, w, 1);
        }
        1 => {
            covered!("tel35_1 discipline plus");
            if period < 3 {
                period += 1;
            }
            set_screen_param(1, period as usize);
            let mut w = get_screen_param(2) as u32;
            exe::screenmanager_set_widget_flags(sm, w as usize, 2);
            exe::screenmanager_set_widget_text_colour(sm, w, tel35_colour(G_GUI_COLOUR_PALE_GREY));
            exe::screenmanager_set_widget_id(sm, w, 2);
            w = w.wrapping_add(1);
            discipline_period_text(period);
            exe::screenmanager_set_widget_text(sm, w, JOB_TEXT);
            w = w.wrapping_add(1);
            if period >= 3 {
                exe::screenmanager_set_widget_flags(sm, w as usize, 6);
                exe::screenmanager_set_widget_text_colour(sm, w, tel35_colour(G_GUI_COLOUR_GREY));
                exe::screenmanager_set_widget_data(sm, w, 0usize);
            }
        }
        3 => {
            covered!("tel35_1 discipline reason");
            let k = tel26_item_value(item);
            let chosen = k.min(4);
            let first = (get_screen_param(2) as u32).wrapping_add(4);
            for j in 0..5u32 {
                let colour = if j == chosen { G_GUI_COLOUR_YELLOW } else { G_GUI_COLOUR_GREY };
                exe::screenmanager_set_widget_text_colour(sm, first.wrapping_add(j), tel35_colour(colour));
            }
            set_screen_param(3, k as usize);
        }
        5 => {
            covered!("tel35_1 discipline confirm");
            exe::fine_fine_player(read_usize(G_FINE), person, period as u32, reason as u32);
            return -9;
        }
        4 => return -9,
        _ => return manager_menu_bar(raw),
    }
    exe::screenmanager_redraw_screen(sm, 0, 0);
    0
}

/// Comparer for `open_discipline_player_screen`.
pub(crate) unsafe extern "C" fn compare_open_discipline_player_screen(person: usize) {
    // simplification: opening a screen does not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn(usize)>(IDX_OPEN_DISCIPLINE_PLAYER_SCREEN)(person)
}

/// Comparer for `draw_discipline_player_screen`: the screen side by side over the display list.
pub(crate) unsafe extern "C" fn compare_draw_discipline_player_screen() {
    let o = original_fn::<unsafe extern "C" fn()>(IDX_DRAW_DISCIPLINE_PLAYER_SCREEN);
    compare_by_display_list_with("Discipline Player screen (draw_discipline_player_screen)", &[], || o(), || draw_discipline_player_screen());
}

/// Comparer for `discipline_player_screen_input`.
pub(crate) unsafe extern "C" fn compare_discipline_player_screen_input(item: u32) -> i32 {
    // simplification: the fine, the redraw and the menu bar commands do not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn(u32) -> i32>(IDX_DISCIPLINE_PLAYER_SCREEN_INPUT)(item)
}

// ---------- batch 318: the history screens (History.cpp) ----------

/// The History.cpp path for the error box.
const HISTORY_CPP: usize = 0x9cec24;
/// The history screens' file name buffer (0xb5dedc, also the "Ok" text).
const HISTORY_FILE_TEXT: usize = 0xb5dedc;
/// The empty text (0xad9c64).
const HISTORY_EMPTY: usize = 0xad9c64;
/// The size of a history record (an entry list: +0 the entries, 8 bytes each (text, picture), +4 their count, +8 the
/// record's name) and of a written history file entry (+0 the file name, 0x104 bytes; +0x104 its title, 0x12c bytes).
const HISTORY_RECORD_SIZE: usize = 0x6c;
const HISTORY_FILE_ENTRY_SIZE: usize = 0x230;
/// The size of a picture name in the history's picture table (screen parameter 4).
const HISTORY_PICTURE_NAME_SIZE: usize = 0x104;

/// `ScreenManager::add_text_item(x1, y1, x2, y2, style, colour, flags, font, text colour, text, 1)` (0x803fd0, thiscall,
/// ret 0x2c).
pub(crate) unsafe fn tel35_text_item(f: [u32; 11]) -> u32 {
    type TextItem = unsafe extern "thiscall" fn(usize, u32, u32, u32, u32, u32, u32, u32, u32, u32, u32, u32) -> u32;
    let g: TextItem = core::mem::transmute(FN_SCREENMANAGER_ADD_TEXT_ITEM);
    g(G_SCREEN_MANAGER, f[0], f[1], f[2], f[3], f[4], f[5], f[6], f[7], f[8], f[9], f[10])
}

/// The C runtime's strncpy (0x9466d0, cdecl).
pub(crate) unsafe fn tel35_strncpy(dst: usize, src: usize, n: u32) {
    exe::at_9466d0(dst, (src) as usize as *const u8, n);
}

/// A cdecl routine of the exe with one argument, returning eax.
pub(crate) unsafe fn tel35_cdecl1(f: usize, a: usize) -> usize {
    let g: unsafe extern "C" fn(usize) -> usize = core::mem::transmute(f);
    g(a)
}

/// The picture of the history record's selected entry: the picture name (`HISTORY_PICTURE_NAME_SIZE` bytes each from
/// parameter 4) of `index`, or the default picture (parameter 7) for -1.
unsafe fn history_picture_name(index: i32) -> usize {
    if index == -1 {
        get_screen_param(7)
    } else {
        get_screen_param(4).wrapping_add((index as u32).wrapping_mul(HISTORY_PICTURE_NAME_SIZE as u32) as usize)
    }
}

/// Rule: the history screen opens on a .his file with the default frame (0x91, 0x4b)-(0x2e9, 0x20f), the text column
/// 0x115 from the left, the picture 0x101 × 0x14f and the pictures under "cm3_history".
///
/// `history_screen_open(name)`: `open_screen` with the builder 0x5f1360, the handler 0x5f1ba0, single instance, the
/// leave routine 0x5f1d60 and 0; when it opens, the parameters: 0 = -1 (no file list), 1..7 = 0, 8..0xb = -1, 0xc =
/// a copy of the name (`set_screen_param` with copy 1), 0xd = -1, 0xe..0x12 = 0x91, 0x4b, 0x2e9, 0x20f, 0x115, 0x13 =
/// "cm3_history", 0x14 = 0x101 and 0x15 = 0x14f.
/// Original: `history_screen_open` (0x5f11c0, History.cpp, cdecl).
pub(crate) unsafe extern "C" fn history_screen_open(name: usize) {
    covered!("tel35_2 open history");
    if exe::screenmanager_open_screen(G_SCREEN_MANAGER, 0x5f1360usize, 0x5f1ba0usize, 1, 0x5f1d60usize, 0) == 0 {
        return;
    }
    set_screen_param(0, usize::MAX);
    for k in 1..8 {
        set_screen_param(k, 0);
    }
    for k in 8..0xc {
        set_screen_param(k, usize::MAX);
    }
    exe::screenmanager_set_screen_param(G_SCREEN_MANAGER, 0xc, name, 1);
    for (k, v) in [(0xd, usize::MAX), (0xe, 0x91), (0xf, 0x4b), (0x10, 0x2e9), (0x11, 0x20f), (0x12, 0x115), (0x13, 0x9cec18),
        (0x14, 0x101), (0x15, 0x14f)] {
        set_screen_param(k, v);
    }
}

/// Rule: the history screen shows a .his file: its title, the record chooser (when the file has more than one), the
/// record's picture and its text word-wrapped to the text column, with an Ok button.
///
/// `history_screen_draw()`: the frame (parameters 0xe..0x11), the text column's left offset (0x12), the file list
/// (0xc) and its count (0xd); the text width = the frame's width − the offset − 0x34. The background picture 0. With a
/// file index (parameter 0) neither in the list nor -1 with no list (-1): the History.cpp 180 box, nothing more. With no
/// file loaded (parameter 1 empty): `history_load_his_file` of "<name>.his" (no list) or of the list's entry, 0; when it
/// fails nothing is built. The full-screen black area (799 × 599; 1919 × 1079 in the 1080 exe, read from it), the frame
/// area in the colour (0, 0x30, 0x70), the title (parameter 1, font 4) from 10 inside the frame, 0x2d high. The record
/// (parameter 6 of the records in parameter 2, `HISTORY_RECORD_SIZE` each): its first entry's picture index written to
/// parameter 8; the picture's frame (yellow) and the picture item 0x400 (the picture of that index under parameter
/// 0x13, or the default picture (parameter 7) when the index is -1 or its file does not exist; an index below -1 is
/// taken without the check); with more than one record (parameter 3), the record's name (font 3) at the text column,
/// the chooser button and its popup area (0x200030, colour (0, 0x80, 0xff)) with one item per record (id 2, data k),
/// and the text 0x2c lower. Two frame areas of the text column (8 and 0x62) and the text area (1, grey) 10 inside,
/// written to parameter 9 (the picture item to 0xa). Each entry's text is cut into lines that fit the width (font 2;
/// a line ends at the last space before the width, the following spaces skipped; the text is cut in place and put
/// back), one item per line with the entry's picture index as data (the first line's item written to parameter 0xb
/// when it is -1), and a blank item after each entry. Last the "Ok" button (id 1).
/// Original: `history_screen_draw` (0x5f1360, History.cpp, cdecl).
pub(crate) unsafe extern "C" fn history_screen_draw() {
    let format: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_CRT_SPRINTF);
    let text: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_LANGLIB_SPRINTF);
    let x1 = get_screen_param(0xe) as i32;
    let y1 = get_screen_param(0xf) as i32;
    let x2 = get_screen_param(0x10) as i32;
    let y2 = get_screen_param(0x11) as i32;
    let indent = get_screen_param(0x12) as i32;
    let files = get_screen_param(0xc);
    let count = get_screen_param(0xd) as i32;
    let width = x2 - indent - x1 - 0x34;
    exe::background_set_picture(0usize);
    let p0 = get_screen_param(0) as i32;
    if !((p0 >= 0 && p0 < count) || (p0 == -1 && count == -1)) {
        tel26_error_box(HISTORY_CPP, 0xb4);
        return;
    }
    if get_screen_param(1) == 0 {
        let loaded = if get_screen_param(0) as i32 == -1 {
            format(HISTORY_FILE_TEXT, 0x9cec50, get_screen_param(0xc));
            exe::history_load_his_file(HISTORY_FILE_TEXT, 0)
        } else {
            exe::history_load_his_file(read_usize(files.wrapping_add(get_screen_param(0).wrapping_mul(4))), 0)
        };
        if loaded == 0 {
            return;
        }
    }
    covered!("tel35_2 draw history");
    let black = tel35_colour(G_GUI_COLOUR_BLACK);
    let pale = tel35_colour(G_GUI_COLOUR_PALE_GREY);
    let yellow = tel35_colour(G_GUI_COLOUR_YELLOW);
    tel26_add_area(current_human_display(), [0, 0, exe_immediate(0x5f14d0 as *const i32) as u32, exe_immediate(0x5f14c8 as *const i32) as u32,
        1, 0, 1, 0, 2, black, u32::MAX]);
    let colour = exe::graphics_rgb_to_pixel(0, 0x30, 0x70, 0);
    tel26_add_area(current_human_display(), [x1 as u32, y1 as u32, x2 as u32, y2 as u32, 1, 0, 1, 0, 0x30, colour, u32::MAX]);
    let (left, right, top) = (x1 + 0xa, x2 - 0xa, y1 + 0xa);
    tel35_text_item([left as u32, top as u32, right as u32, (top + 0x2d) as u32, 0x30, black, 0xc, 4, pale, get_screen_param(1) as u32, 1]);
    let mut y = top + 0x37;
    let records = get_screen_param(2);
    let record = records.wrapping_add((get_screen_param(6) as u32).wrapping_mul(HISTORY_RECORD_SIZE as u32) as usize);
    let first = read_i32(read_usize(record) + 4);
    set_screen_param(8, first as usize);
    let pic_x2 = get_screen_param(0x14) as i32 + x1 + 0xc;
    let pic_y2 = get_screen_param(0x15) as i32 + y + 2;
    tel35_text_item([left as u32, y as u32, pic_x2 as u32, pic_y2 as u32, 0x61, colour, 1, 2, yellow, HISTORY_EMPTY as u32, 1]);
    let picture = if first == -1 {
        get_screen_param(7)
    } else if first < -1 {
        history_picture_name(first)
    } else if exe::utils_file_exists(exe::utils_build_file_path(get_screen_param(0x13), history_picture_name(first))) != 0 {
        history_picture_name(first)
    } else {
        get_screen_param(7)
    };
    let path = exe::utils_build_file_path(get_screen_param(0x13), picture);
    let picture_item = tel26_add_item(current_human_display(), [0x400, (x1 + 0xc) as u32, (y + 2) as u32, pic_x2 as u32, pic_y2 as u32, 0, 0, 1,
        black, black, 0xc, 2, pale, path as u32, 1, 0, 0, u32::MAX]);
    if get_screen_param(3) as i32 > 1 {
        covered!("tel35_2 history record chooser");
        let x = indent + x1;
        tel35_text_item([x as u32, y as u32, right as u32, (y + 0x22) as u32, 0x32, colour, 0xc, 3, yellow, (record + 8) as u32, 1]);
        let popup_colour = exe::graphics_rgb_to_pixel(0, 0x80, 0xff, 0);
        let button = tel26_add_button([(x + 5) as u32, (y + 5) as u32, (x + 0x14) as u32, (y + 0x19) as u32, 0x20, black, 0xc, 2, yellow,
            HISTORY_EMPTY as u32, 0, 0]);
        let popup = tel26_add_area(current_human_display(), [0, 0, 0, 0, 0, 0, 0, 0, 0x200030, popup_colour, button]);
        let mut k = 0i32;
        while k < get_screen_param(3) as i32 {
            let name = records.wrapping_add(8).wrapping_add((k as u32).wrapping_mul(HISTORY_RECORD_SIZE as u32) as usize);
            tel26_add_item(current_human_display(), [2, 0, 0, 0, 0, 0, 0, 0x90, popup_colour, yellow, 1, 1, black, name as u32, 0, 2, k as u32, popup]);
            k += 1;
        }
        y += 0x2c;
    }
    let x = x1 + indent;
    let bottom = y2 - 0x32;
    tel26_add_area(current_human_display(), [x as u32, y as u32, right as u32, bottom as u32, 1, 0, 0xf, 0, 8, colour, u32::MAX]);
    tel26_add_area(current_human_display(), [x as u32, y as u32, right as u32, bottom as u32, 1, 0, 0xf, 0, 0x62, colour, u32::MAX]);
    let area = tel26_add_area(current_human_display(), [(x + 0xa) as u32, (y + 0xa) as u32, right as u32, (y2 - 0x3c) as u32, 1, 0, 0xf, 0, 1,
        tel35_colour(G_GUI_COLOUR_GREY), u32::MAX]);
    set_screen_param(9, area as i16 as isize as usize);
    set_screen_param(0xa, picture_item as i16 as isize as usize);
    let mut row = 0u32;
    let mut k = 0usize;
    while (k as i32) < read_i32(record + 4) {
        let mut s = read_usize(read_usize(record) + k * 8) as *mut u8;
        if *s != 0 {
            let mut c = *s;
            loop {
                let mut i = 0isize;
                let mut b = c;
                loop {
                    *s.offset(i) = b;
                    b = *s.offset(i + 1);
                    i += 1;
                    *s.offset(i) = 0;
                    if !(exe::font_text_width(2usize, s) < width && b != 0) {
                        break;
                    }
                }
                *s.offset(i) = b;
                while b != b' ' && b != 0 {
                    i -= 1;
                    b = *s.offset(i);
                }
                b = *s.offset(i);
                *s.offset(i) = 0;
                let value = read_u32(read_usize(record) + k * 8 + 4);
                let line = tel26_add_item(current_human_display(), [1, 0, 0, 0, 0, 0, row, 1, black, 0, 1, 2, pale, s as u32, 0, 0, value, area]);
                row += 1;
                if get_screen_param(0xb) as i32 == -1 {
                    set_screen_param(0xb, line as i16 as isize as usize);
                }
                *s.offset(i) = b;
                if b == b' ' {
                    loop {
                        let a = *s.offset(i + 1);
                        i += 1;
                        if a != b' ' {
                            break;
                        }
                    }
                }
                let a = *s.offset(i);
                s = s.offset(i);
                if a == 0 {
                    break;
                }
                c = a;
            }
        }
        let value = read_u32(read_usize(record) + k * 8 + 4);
        tel26_add_item(current_human_display(), [1, 0, 0, 0, 0, 0, row, 1, black, 0, 1, 2, pale, HISTORY_EMPTY as u32, 0, 0, value, area]);
        row += 1;
        k += 1;
    }
    text(HISTORY_FILE_TEXT, 0x990f7c);
    tel26_add_button([left as u32, (y2 - 0x28) as u32, right as u32, (y2 - 0xa) as u32, 0x30, tel35_colour(G_GUI_COLOUR_GREY), 0xc, 4, pale,
        HISTORY_FILE_TEXT as u32, 1, 0]);
}

/// Rule: scrolling the history text shows the picture of the first visible line's entry; Ok closes, a record of the
/// chooser shows that record.
///
/// `history_screen_handle_event(item)`: with no file loaded (parameter 1) -9. The first visible widget of the text
/// (the scroll row of the text area, parameter 9, + the first line's widget, parameter 0xb, + 7): its data (0 for
/// -1) differing from parameter 8 becomes parameter 8, and the picture item (parameter 0xa) gets that picture's path
/// (under parameter 0x13; the default picture, parameter 7, for -1); redraw. Then the item: -1 gives 0; id 1 (Ok) -9;
/// id 2 (a record) writes its data to parameter 6 and gives -11; others 0.
/// Original: `history_screen_handle_event` (0x5f1ba0, History.cpp, cdecl).
pub(crate) unsafe extern "C" fn history_screen_handle_event(raw: u32) -> i32 {
    if get_screen_param(1) == 0 {
        return -9;
    }
    let scroll = exe::screenmanager_get_area_scroll_row(G_SCREEN_MANAGER, get_screen_param(9)) as u32;
    let shown = scroll.wrapping_add(get_screen_param(0xb) as u32).wrapping_add(7) as i16;
    if tel26_item_value(shown) != get_screen_param(8) as u32 {
        covered!("tel35_2 history picture follows");
        set_screen_param(8, tel26_item_value(shown) as usize);
        let path = exe::utils_build_file_path(get_screen_param(0x13), history_picture_name(get_screen_param(8) as i32));
        exe::screenmanager_set_widget_text(G_SCREEN_MANAGER, get_screen_param(0xa) as u32, path);
        exe::screenmanager_redraw_screen(G_SCREEN_MANAGER, 0, 0);
    }
    let item = raw as i16;
    if item == -1 {
        return 0;
    }
    match tel26_item_id(item) {
        1 => -9,
        2 => {
            set_screen_param(6, tel26_item_value(item) as usize);
            -11
        }
        _ => 0,
    }
}

/// Rule: leaving the history screen frees the loaded file: the picture table, and each record's entry texts, entry
/// list and the record table.
///
/// `history_screen_free()`: parameter 1 = 0; the picture table (parameter 4) freed and cleared when there is one;
/// parameter 7 = 0; with a record table (parameter 2): for each of the parameter 3 records whose entry list is not
/// null, every non-null entry text freed, then the list; then the table, and parameters 2 and 3 = 0.
/// Original: `history_screen_free` (0x5f1d60, History.cpp, cdecl).
pub(crate) unsafe extern "C" fn history_screen_free() {
    set_screen_param(1, 0);
    if get_screen_param(4) != 0 {
        exe::crt_free(get_screen_param(4));
        set_screen_param(4, 0);
    }
    set_screen_param(7, 0);
    let records = get_screen_param(2);
    let count = get_screen_param(3) as i32;
    if records == 0 {
        return;
    }
    covered!("tel35_2 history free");
    for r in 0..count.max(0) as usize {
        let record = records + r * HISTORY_RECORD_SIZE;
        if read_usize(record) == 0 {
            continue;
        }
        let mut j = 0usize;
        while (j as i32) < read_i32(record + 4) {
            let t = read_usize(read_usize(record) + j * 8);
            if t != 0 {
                exe::crt_free(t);
            }
            j += 1;
        }
        exe::crt_free(read_usize(record));
    }
    exe::crt_free(records);
    set_screen_param(2, 0);
    set_screen_param(3, 0);
}

/// Rule: the written history screen opens on a tab with no file list yet.
///
/// `history_written_screen_open(tab)`: `open_screen` with the builder 0x5f2c00, the handler 0x5f31c0, not single, the
/// leave routine 0x5f33d0 and 0; parameter 0 = the tab, 1..4 = 0.
/// Original: `history_written_screen_open` (0x5f2b80, History.cpp, cdecl).
pub(crate) unsafe extern "C" fn history_written_screen_open(tab: usize) {
    covered!("tel35_2 open written history");
    if exe::screenmanager_open_screen(G_SCREEN_MANAGER, 0x5f2c00usize, 0x5f31c0usize, 0, 0x5f33d0usize, 0) == 0 {
        return;
    }
    set_screen_param(0, tab);
    for k in 1..5 {
        set_screen_param(k, 0);
    }
}

/// Rule: the written history screen lists, under the tabs Nations, Competitions, Leagues, Clubs and Players, the
/// titles of the .his files of the chosen tab's category.
///
/// `history_written_screen_draw()`: ten tab records (0xd4 bytes, built by the runtime's vector constructor with
/// `MenuItem::MenuItem`); the "CM3_HISTORY" folder; the tab (parameter 0), the list (1) and its count (2). The random
/// background picture, the title "History" (dark blue, pale grey), the menu bar (4, 0) and the tab bar of five tabs
/// (Nations 1, Competitions 2, Leagues 3, Clubs 0, Players 4, all kind 1) from 0x50 to 0x221. With no list: a block of
/// 100 file entries (`HISTORY_FILE_ENTRY_SIZE`, `operator new`; null: the History.cpp 1235 box and nothing more); every
/// "*.his" of the folder (`file_find_first`/`file_find_next`) whose name without its extension has the tab's category
/// (`history_get_his_file_category`) and a title (`history_get_his_file_title`) is copied (name 0x104, title 0x12c,
/// each cut at its last byte); a 101st shows the History.cpp 1270 box and the screen stops there (the search left open,
/// the block not kept); the entries sorted by title (qsort with 0x5f3410); parameter 1 = the block and 2 = the count;
/// the search closed. The list area (0x6e, top)-(0x30c, bottom) with (bottom − top − 16) / the height of font 3 rows,
/// one button per entry (" <title>", id 2, the entry as data), scrolled to parameter 3 and written to parameter 4; the
/// Back and Next buttons.
/// Original: `history_written_screen_draw` (0x5f2c00, History.cpp, cdecl).
pub(crate) unsafe extern "C" fn history_written_screen_draw() {
    let text: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_LANGLIB_SPRINTF);
    let format: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_CRT_SPRINTF);
    let mut tabs = [0u32; 0xd4 * 10 / 4];
    let t = tabs.as_mut_ptr() as usize;
    exe::crt_vector_constructor_iterator(t, 0xd4, 0xa, 0x4568f0usize, 0x5a53c0usize);
    let mut folder = [0u8; 0x104];
    tel26_copy_text(folder.as_mut_ptr(), exe::utils_build_file_path(0x9cedb8usize, HISTORY_EMPTY) as *const u8);
    let tab = get_screen_param(0);
    let mut list = get_screen_param(1);
    let mut count = get_screen_param(2) as i32;
    exe::background_set_random_picture();
    text(JOB_TEXT, 0x9914d4, HISTORY_EMPTY);
    exe::screenmanager_add_screen_title(G_SCREEN_MANAGER, tel35_colour(G_GUI_COLOUR_DARK_BLUE), tel35_colour(G_GUI_COLOUR_PALE_GREY), JOB_TEXT);
    exe::menubar_build(4, 0);
    for (k, (label, link)) in [(0x9c9f64u32, 1u32), (0x98ed18, 2), (0x9cedcc, 3), (0x9cedc4, 0), (0x990a80, 4)].into_iter().enumerate() {
        let entry = t + k * 0xd4;
        text(entry + 4, label as usize);
        write_u32(entry + 0xcc, 1);
        write_u32(entry + 0xd0, link);
    }
    let (mut top, mut bottom) = (0x50i32, 0x221i32);
    exe::gui_add_tab_bar(t, 5, tab as i32, &mut top, &mut bottom, 1);
    if list == 0 {
        covered!("tel35_2 written history file search");
        let block = exe::crt_operator_new(0xdac0);
        count = 0;
        if block == 0 {
            tel26_error_box(HISTORY_CPP, 0x4d3);
            exe::crt_vector_destructor_iterator(t, 0xd4, 0xa, 0x5a53c0usize);
            return;
        }
        let mut pattern = [0u8; 0x104];
        let mut found = [0u8; 0x114];
        exe::crt_makepath(pattern.as_mut_ptr(), 0usize, folder.as_ptr() as usize, 0x989ad8usize, 0x9cedb0usize);
        if exe::file_find_first(pattern.as_ptr() as usize, found.as_mut_ptr() as usize, 0) == 0 {
            let mut entry = block;
            loop {
                tel26_copy_text(pattern.as_mut_ptr(), found.as_ptr().add(0x10));
                let mut i = tel35_c_string_len(pattern.as_ptr()) as isize - 1;
                while i >= 0 {
                    if pattern[i as usize] == b'.' {
                        pattern[i as usize] = 0;
                        break;
                    }
                    i -= 1;
                }
                if tel35_cdecl1(0x5f2580, pattern.as_ptr() as usize) as u32 == tab as u32 {
                    let title = tel35_cdecl1(0x5f2700, pattern.as_ptr() as usize);
                    if title != 0 {
                        if count >= 0x64 {
                            tel26_error_box(HISTORY_CPP, 0x4f6);
                            exe::crt_vector_destructor_iterator(t, 0xd4, 0xa, 0x5a53c0usize);
                            return;
                        }
                        tel35_strncpy(entry, pattern.as_ptr() as usize, 0x104);
                        write_u8(entry + 0x103, 0);
                        tel35_strncpy(entry + 0x104, title, 0x12c);
                        write_u8(entry + 0x104 + 0x12b, 0);
                        count += 1;
                        entry += HISTORY_FILE_ENTRY_SIZE;
                    }
                }
                if exe::file_find_next(found.as_mut_ptr()) != 0 {
                    break;
                }
            }
            if count != 0 {
                exe::crt_qsort(block, count as u32, HISTORY_FILE_ENTRY_SIZE as u32, 0x5f3410usize);
            }
        }
        set_screen_param(1, block);
        set_screen_param(2, count as usize);
        exe::file_find_close(found.as_ptr() as usize);
        list = block;
    }
    let rows = ((bottom - top - 0x10) / exe::font_get_height(3)) as u8 as u32;
    let area = tel26_add_area(current_human_display(), [0x6e, top as u32, 0x30c, bottom as u32, 1, 0, rows, 0, 2, 0, u32::MAX]);
    for k in 0..count.max(0) as usize {
        let entry = list + k * HISTORY_FILE_ENTRY_SIZE;
        format(JOB_TEXT, 0x987ff0, entry + 0x104);
        tel26_area_button([area, 0, k as u32, 1, 0, 1, 3, tel35_colour(G_GUI_COLOUR_PALE_GREY), JOB_TEXT as u32, 2, entry as u32]);
    }
    let scroll = get_screen_param(3);
    let d = current_human_display();
    if area as i16 != -1 {
        exe::area_set_scroll_row(d.wrapping_add(4).wrapping_add((area as i16 as isize as usize).wrapping_mul(0xbf1)), scroll);
    }
    set_screen_param(4, area as i16 as isize as usize);
    tel26_back_next();
    exe::crt_vector_destructor_iterator(t, 0xd4, 0xa, 0x5a53c0usize);
}

/// The length of a C string (the original's repne scasb).
pub(crate) unsafe fn tel35_c_string_len(s: *const u8) -> usize {
    let mut n = 0;
    while *s.add(n) != 0 {
        n += 1;
    }
    n
}

/// Rule: on the written history screen a tab click changes the category and drops the list; an entry opens its
/// history screen.
///
/// `history_written_screen_handle_click(item)`: with an item, the list's scroll row (area of parameter 4) is kept in
/// parameter 3. Id 1 (a tab) with a tab other than parameter 0: parameter 0 = that tab, the list (parameter 1) deleted
/// (`operator delete`) and parameters 1 and 2 = 0, -11. Id 2 (an entry): its file name (0x104 bytes, cut at its last
/// byte) opens the history screen (`history_screen_open`), -11. Otherwise (the same tab included) the menu bar's
/// command, then its object link.
/// Original: `history_written_screen_handle_click` (0x5f31c0, History.cpp, cdecl).
pub(crate) unsafe extern "C" fn history_written_screen_handle_click(raw: u32) -> i32 {
    let tab = get_screen_param(0) as u32;
    let list = get_screen_param(1);
    let item = raw as i16;
    if item != -1 {
        set_screen_param(3, exe::screenmanager_get_area_scroll_row(G_SCREEN_MANAGER, get_screen_param(4)));
    }
    let id = tel26_item_id(item);
    if id == 1 && tel26_item_value(item) != tab {
        covered!("tel35_2 written history tab");
        set_screen_param(0, tel26_item_value(item) as usize);
        if list != 0 {
            exe::crt_operator_delete(list);
        }
        set_screen_param(1, 0);
        set_screen_param(2, 0);
        return -11;
    }
    if id == 2 {
        covered!("tel35_2 written history entry");
        let mut name = [0u8; 0x104];
        tel35_strncpy(name.as_mut_ptr() as usize, tel26_item_value(item) as usize, 0x104);
        name[0x103] = 0;
        tel35_cdecl1(0x5f11c0, name.as_ptr() as usize);
        return -11;
    }
    manager_menu_bar(raw)
}

/// Rule: leaving the written history screen deletes the file list.
///
/// `history_written_screen_close()`: the list (parameter 1) deleted (`operator delete`) when there is one; parameters
/// 1 and 2 = 0.
/// Original: `history_written_screen_close` (0x5f33d0, History.cpp, cdecl).
pub(crate) unsafe extern "C" fn history_written_screen_close() {
    let list = get_screen_param(1);
    if list != 0 {
        exe::crt_operator_delete(list);
    }
    set_screen_param(1, 0);
    set_screen_param(2, 0);
}

/// Comparer for `history_screen_open`.
pub(crate) unsafe extern "C" fn compare_history_screen_open(name: usize) {
    // simplification: opening a screen does not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn(usize)>(IDX_HISTORY_SCREEN_OPEN)(name)
}

/// Comparer for `history_screen_draw`: side by side over the display list, the file name buffer and the parameters;
/// loading the file does not run twice (only the original runs then).
pub(crate) unsafe extern "C" fn compare_history_screen_draw() {
    let o = original_fn::<unsafe extern "C" fn()>(IDX_HISTORY_SCREEN_DRAW);
    if get_screen_param(1) == 0 {
        // simplification: loading the .his file allocates the records; the first build only in the original
        return o();
    }
    compare_by_display_list_with("History screen (history_screen_draw)", &[(HISTORY_FILE_TEXT, 0x104)], || o(), || history_screen_draw());
}

/// Comparer for `history_screen_handle_event`.
pub(crate) unsafe extern "C" fn compare_history_screen_handle_event(item: u32) -> i32 {
    // simplification: the redraw does not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn(u32) -> i32>(IDX_HISTORY_SCREEN_HANDLE_EVENT)(item)
}

/// Comparer for `history_screen_free`.
pub(crate) unsafe extern "C" fn compare_history_screen_free() {
    // simplification: freeing does not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn()>(IDX_HISTORY_SCREEN_FREE)()
}

/// Comparer for `history_written_screen_open`.
pub(crate) unsafe extern "C" fn compare_history_written_screen_open(tab: usize) {
    // simplification: opening a screen does not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn(usize)>(IDX_HISTORY_WRITTEN_SCREEN_OPEN)(tab)
}

/// Comparer for `history_written_screen_draw`: side by side over the display list when the list exists (the file
/// search allocates it: the first build only in the original).
pub(crate) unsafe extern "C" fn compare_history_written_screen_draw() {
    let o = original_fn::<unsafe extern "C" fn()>(IDX_HISTORY_WRITTEN_SCREEN_DRAW);
    if get_screen_param(1) == 0 {
        // simplification: the file search allocates the list; the first build only in the original
        return o();
    }
    compare_by_display_list_with("Written history screen (history_written_screen_draw)", &[], || o(), || history_written_screen_draw());
}

/// Comparer for `history_written_screen_handle_click`.
pub(crate) unsafe extern "C" fn compare_history_written_screen_handle_click(item: u32) -> i32 {
    // simplification: opening a screen and the menu bar commands do not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn(u32) -> i32>(IDX_HISTORY_WRITTEN_SCREEN_HANDLE_CLICK)(item)
}

/// Comparer for `history_written_screen_close`.
pub(crate) unsafe extern "C" fn compare_history_written_screen_close() {
    // simplification: deleting does not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn()>(IDX_HISTORY_WRITTEN_SCREEN_CLOSE)()
}

// ---------- batch 318: the retire and holiday screens and two list comparers (manager_screens.cpp) ----------

/// A thiscall routine of the exe with one argument.
pub(crate) unsafe fn tel35_this1(f: usize, this: usize, a: usize) -> usize {
    let g: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(f);
    g(this, a)
}

/// A thiscall routine of the exe with two arguments.
pub(crate) unsafe fn tel35_this2(f: usize, this: usize, a: usize, b: usize) -> usize {
    let g: unsafe extern "thiscall" fn(usize, usize, usize) -> usize = core::mem::transmute(f);
    g(this, a, b)
}

/// `HUMAN_MANAGER::get_holiday_option(option, 0)` (0x5fea50) of the human manager table: the option's byte.
unsafe fn holiday_option(option: u32) -> u8 {
    exe::human_manager_get_holiday_option(read_usize(G_HUMAN_MANAGER), option, 0usize)
}

/// `HUMAN_MANAGER::set_holiday_option(option, value, 0)` (0x5feb60, thiscall, ret 0xc).
unsafe fn set_holiday_option(option: u32, value: i32) {
    exe::human_manager_set_holiday_option(read_usize(G_HUMAN_MANAGER), option, value, 0)
}

/// The background picture of the manager's screens: his club's, else his national team's, else a random one.
unsafe fn manager_job_background(manager: usize) {
    let manager = Staff(manager);
    let club = manager.club_job().addr();
    let nation = manager.national_job().addr();
    if club != 0 {
        exe::background_set_club_picture(club, 0, 0);
    } else if nation != 0 {
        exe::background_set_club_picture(nation, 0, 0);
    } else {
        exe::background_set_random_picture();
    }
}

/// The No (id 1) and Yes (id 2) buttons of a manager confirm screen: the area (0x64, 0x22b)-(0x316, 0x24e), two columns
/// with the weights `weights` (3, 1).
unsafe fn manager_no_yes(weights: &[u8; 2]) {
    let text: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_LANGLIB_SPRINTF);
    let area = tel26_add_area(current_human_display(), [0x64, 0x22b, 0x316, 0x24e, 2, weights.as_ptr() as u32, 1, 0, 1, 0, u32::MAX]);
    text(JOB_TEXT, 0x98e8cc);
    tel26_area_button([area, 0, 0, 0x30, tel35_colour(G_GUI_COLOUR_GREY), 0xc, 3, tel35_colour(G_GUI_COLOUR_PALE_GREY), JOB_TEXT as u32, 1, 0]);
    text(JOB_TEXT, 0x98e8d0);
    tel26_area_button([area, 1, 0, 0x30, tel35_colour(G_GUI_COLOUR_GREY), 0xc, 3, tel35_colour(G_GUI_COLOUR_PALE_GREY), JOB_TEXT as u32, 2, 0]);
}

/// Rule: the retire screen opens for the current human manager.
