// ---------- batch 318: the staff note screen (notes.cpp) ----------

/// The staff note (notes.cpp) fields read by the screen: the text at +4, the reminder date (+0x103 the day/year dword,
/// +0x107 the leap-year dword), the date it was written at +0x10b, the reason byte at +0x113.
const NOTE_TEXT: usize = 0x4;
const NOTE_REMINDER_DATE: usize = 0x103;
const NOTE_WRITTEN_DATE: usize = 0x10b;
const NOTE_REASON: usize = 0x113;

/// `Notes::<method>` on `G_NOTES` with one argument (thiscall, ret 4).
unsafe fn notes_call1(f: usize, a: usize) -> usize {
    let g: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(f);
    g(read_usize(G_NOTES), a)
}

/// `Notes::<method>` on `G_NOTES` with two arguments (thiscall, ret 8).
unsafe fn notes_call2(f: usize, a: usize, b: usize) -> usize {
    let g: unsafe extern "thiscall" fn(usize, usize, usize) -> usize = core::mem::transmute(f);
    g(read_usize(G_NOTES), a, b)
}

/// Rule: the staff note screen opens to create a note on a person, or to edit the human's note on him: the text, the
/// reason and, when the reminder is a week or four weeks after the writing, the matching reminder choice.
///
/// `notes_open_staff_note_screen(person)`: `open_screen` with the builder 0x796340, the handler 0x796b30, single
/// instance, the no-op leave routine 0x5a8f60 and 0; when it opens, the slot's human and `Notes::find_note(human,
/// person)` on `G_NOTES`. No note: `Notes::clear_edit_text(human)`, the reminder choice 0, the reason 0, not editing.
/// A note: editing, `Notes::set_edit_text(human, note text)`; the reminder choice is 0xff (a date) when
/// `Date::days_since` from the reminder date to the written date is 7 or 28, else 0; the reason is the note's byte.
/// Then the parameters: 0 the person's id, 1 today (the address of `G_CURRENT_DATE`), 2 the reminder choice, 3 the
/// reason, 4 editing (all sign-extended), 5 `Notes::get_edit_text(human)`, 6 and 7 the note's written and reminder
/// dates (0 without a note), 8 the reminder choice again.
/// Original: `notes_open_staff_note_screen` (0x7961b0, notes.cpp, cdecl).
pub(crate) unsafe extern "C" fn notes_open_staff_note_screen(person: usize) {
    if exe::screenmanager_open_screen(G_SCREEN_MANAGER, 0x796340usize, 0x796b30usize, 1, 0x5a8f60usize, 0) == 0 {
        return;
    }
    covered!("tel36_7 open the staff note");
    let slot = read_i16(G_SCREEN_MANAGER_CURRENT_SLOT) as isize;
    let human = read_usize((G_SCREEN_RECORDS_MANAGER as isize + slot * 0x300) as usize);
    let note = notes_call2(0x795750, human, person);
    let (choice, reason, editing) = if note == 0 {
        notes_call1(0x795a60, human);
        (0u8, 0u8, 0u8)
    } else {
        notes_call2(0x795a10, human, note + NOTE_TEXT);
        let days = exe::date_days_since(note + NOTE_WRITTEN_DATE, read_u32(note + NOTE_REMINDER_DATE), read_u32(note + NOTE_REMINDER_DATE + 4));
        let choice = if days == 7 || days == 0x1c { 0xff } else { 0 };
        (choice, read_u8(note + NOTE_REASON), 1)
    };
    let text = notes_call1(0x7959e0, human);
    set_screen_param(0, read_u32(person) as usize);
    set_screen_param(1, G_CURRENT_DATE);
    set_screen_param(2, choice as i8 as isize as usize);
    set_screen_param(3, reason as i8 as isize as usize);
    set_screen_param(4, editing as usize);
    set_screen_param(5, text);
    if note != 0 {
        set_screen_param(6, note + NOTE_WRITTEN_DATE);
        set_screen_param(7, note + NOTE_REMINDER_DATE);
    } else {
        set_screen_param(6, 0);
        set_screen_param(7, 0);
    }
    set_screen_param(8, choice as i8 as isize as usize);
}

/// Rule: the staff note screen shows the person in his club's colours ("Create" or "Edit Staff Note"), the sentence
/// with his link, the note's text entry, the three reminder choices and, editing, the reminder date; then the five
/// reasons (those not valid for the person greyed) and Cancel / Confirm (and Delete when editing).
///
/// `notes_draw_staff_note_screen()`: a local Text; the person (parameter 0), the reminder choice (2, a char), the
/// reason (3), editing (4, a char), the text (5), the written date (6) and the date choice (8, a char); the human of the
/// slot. The club: the person's `staff::CLUB_JOB`, else the club of `TRANSFER_RULES_DEFAULT_CLUB_KEY`. The person's
/// background picture; the title: his name (500 bytes, style 1) in the club's kit 1 colours; the subtitle "Edit Staff
/// Note" (editing) or "Create Staff Note"; rows = 0x195 / the height of font 3. Area 1 (0x6e, 0x8c)-(0x30c, 0x221),
/// seven columns (2, 20, 2, 10, 2, 4, 3), kind 2: the sentence 0xa69fec (0x64, the name) with the person's link
/// (0x7d7) drawn wrapped from row 0 (font 3, pale grey). Area 2, three columns (2, 5, 36), kind 1, from two rows below
/// (row R): "Note :" (column 1) and the text entry (flags 0x80018, row R, colour `JOB_COLOUR_BDE8`, the text, limit
/// 0xfe, id 8, in area 2). R + 2: "Reminder Required ?" in area 1. Area 3, two columns (2, 17), kind 1, from R + 4: the
/// three reminder labels (`notes_get_reminder_label` k, 2000 bytes) as buttons id 7 with data k, the chosen one
/// `JOB_COLOUR_BDEC` and the others pale grey; editing, with a written date after 1980, the long date string (1000
/// bytes) as a button id 7 with data -1 (`JOB_COLOUR_BDEC` when the choice is 0xff and the date choice is set). Two
/// rows below "Reason for note:" in area 1 and, from two rows further, the five reasons (`notes_get_reason_label` k,
/// 2000 bytes, 2) in area 3: not valid for the person (`notes_is_reason_valid_for_staff(human, person, k)`) grey with
/// id 0, otherwise id 3 with data k, the chosen one `JOB_COLOUR_BDEC`. The menu bar (4, 0) and the button area
/// (0x64, 0x22b)-(0x316, 0x24e) in the club's background colour: editing, columns 1, 4, 1 with "Delete" (id 6),
/// "Cancel" (4) and "Confirm" (5); otherwise columns 3, 1 with "Cancel" and "Confirm".
/// Original: `notes_draw_staff_note_screen` (0x796340, notes.cpp, cdecl).
pub(crate) unsafe extern "C" fn notes_draw_staff_note_screen() {
    let text = tel36_langlib();
    let columns: [u8; 7] = [2, 0x14, 2, 0xa, 2, 4, 3];
    let three: [u8; 3] = [1, 4, 1];
    let weights: [u8; 7] = [2, 0x11, 3, 1, 2, 5, 0x24];
    let mut tx = [0u32; 8];
    let t = tx.as_mut_ptr() as usize;
    exe::new_text(tx.as_mut_ptr() as *mut usize, 0usize);
    let slot = read_i16(G_SCREEN_MANAGER_CURRENT_SLOT) as isize;
    let human = read_usize((G_SCREEN_RECORDS_MANAGER as isize + slot * 0x300) as usize);
    let person = Staff(tel36_staff_param(0));
    let choice = get_screen_param(2) as u8;
    let reason = get_screen_param(3) as u32;
    let editing = get_screen_param(4) as u8;
    let note_text = get_screen_param(5);
    let written = get_screen_param(6);
    let date_choice = get_screen_param(8) as u8;
    covered!("tel36_7 draw the staff note");
    let own = person.club_job().addr();
    let club = if own != 0 {
        own
    } else {
        read_usize(G_CLUB_TABLE).wrapping_add(read_u32(TRANSFER_RULES_DEFAULT_CLUB_KEY).wrapping_mul(club::SIZE as u32) as usize)
    };
    exe::background_set_staff_picture(person.addr(), 0, 0);
    let (mut fore, mut back) = (0u32, 0u32);
    exe::database_get_club_kit_colours(club, 1, &mut fore, &mut back);
    let mut name = [0u8; 0x1f4];
    exe::database_format_staff_name(person, name.as_mut_ptr() as usize, 0x1f4, 1);
    exe::screenmanager_add_screen_title(G_SCREEN_MANAGER, back, fore, name.as_ptr() as usize);
    text(JOB_TEXT, if editing != 0 { 0xa6a058 } else { 0xa6a044 });
    exe::screenmanager_add_screen_subtitle(G_SCREEN_MANAGER, JOB_TEXT, 1);
    let rows = (0x195 / exe::font_get_height(3)) as u8 as u32;
    let pale = job_colour(JOB_COLOUR_3184);
    let first = tel26_add_area(current_human_display(), [0x6e, 0x8c, 0x30c, 0x221, 7, columns.as_ptr() as u32, rows, 0, 2, 0, u32::MAX]);
    text(JOB_TEXT, 0xa69fec, 0x64, name.as_ptr());
    exe::text_set_string(t, JOB_TEXT as *const u8);
    exe::text_add_link(t, name.as_ptr(), 0x7d7, person);
    let mut row = 0i32;
    tel35_text_draw_wrapped(t, first, 0x6e, 0x30c, &mut row, 3, pale, 0, 0);
    row += 2;
    let second = tel26_add_area(current_human_display(), [0x6e, 0x8c, 0x30c, 0x221, 3, weights.as_ptr().wrapping_add(4) as u32, rows, 0, 1, 0, u32::MAX]);
    text(JOB_TEXT, 0xa69fe4);
    tel26_area_text([second, 1, row as u32, 1, 0, 1, 3, pale, JOB_TEXT as u32]);
    tel26_add_item(current_human_display(), [0x80018, 0, 0, 0, 0, 2, row as u32, 1, 0, 0, 1, 3, job_colour(JOB_COLOUR_BDE8),
        note_text as u32, 0xfe, 8, 0, second]);
    row += 2;
    text(JOB_TEXT, 0xa69fd0);
    tel26_area_button([first, 1, row as u32, 1, 0, 1, 3, pale, JOB_TEXT as u32, 0, 0]);
    row += 2;
    let third = tel26_add_area(current_human_display(), [0x6e, 0x8c, 0x30c, 0x221, 2, weights.as_ptr() as u32, rows, 0, 1, 0, u32::MAX]);
    for k in 0..3u8 {
        exe::notes_get_reminder_label(read_usize(G_NOTES), JOB_TEXT, 0x7d0, k as u32);
        let colour = if choice != k { pale } else { job_colour(JOB_COLOUR_BDEC) };
        tel26_area_button([third, 1, row as u32, 1, 0, 1, 3, colour, JOB_TEXT as u32, 7, k as u32]);
        row += 1;
    }
    if written != 0 && editing != 0 && read_u16(written + 2) > 0x7bc {
        covered!("tel36_7 staff note reminder date");
        exe::date_get_long_date_string(written, JOB_TEXT, 0x3e8, 0xff);
        let colour = if choice == 0xff && date_choice != 0 { job_colour(JOB_COLOUR_BDEC) } else { pale };
        tel26_area_button([third, 1, row as u32, 1, 0, 1, 3, colour, JOB_TEXT as u32, 7, u32::MAX]);
    }
    row += 2;
    text(JOB_TEXT, 0xa69fbc);
    tel26_area_button([first, 1, row as u32, 1, 0, 1, 3, pale, JOB_TEXT as u32, 0, 0]);
    row += 2;
    for k in 0..5u8 {
        exe::notes_get_reason_label(read_usize(G_NOTES), JOB_TEXT, 0x7d0, k as u32, 2);
        if exe::notes_is_reason_valid_for_staff(read_usize(G_NOTES), human, person.addr(), k as u32) == 0 {
            tel26_area_button([third, 1, row as u32, 1, 0, 1, 3, job_colour(JOB_COLOUR_317E), JOB_TEXT as u32, 0, 0]);
        } else {
            let colour = if reason != k as u32 { pale } else { job_colour(JOB_COLOUR_BDEC) };
            tel26_area_button([third, 1, row as u32, 1, 0, 1, 3, colour, JOB_TEXT as u32, 3, k as u32]);
        }
        row += 1;
    }
    exe::menubar_build(4, 0);
    let grey = job_colour(JOB_COLOUR_317E);
    if editing != 0 {
        let bar = tel26_add_area(current_human_display(), [0x64, 0x22b, 0x316, 0x24e, 3, three.as_ptr() as u32, 1, 0, 1, back, u32::MAX]);
        text(JOB_TEXT, 0xa69fb4);
        tel26_area_button([bar, 0, 0, 0x30, grey, 0xc, 3, pale, JOB_TEXT as u32, 6, 0]);
        text(JOB_TEXT, 0x98a1a0);
        tel26_area_button([bar, 1, 0, 0x30, grey, 0xc, 3, pale, JOB_TEXT as u32, 4, 0]);
        text(JOB_TEXT, 0x98a198);
        tel26_area_button([bar, 2, 0, 0x30, grey, 0xc, 3, pale, JOB_TEXT as u32, 5, 0]);
    } else {
        let bar = tel26_add_area(current_human_display(), [0x64, 0x22b, 0x316, 0x24e, 2, weights.as_ptr().wrapping_add(2) as u32, 1, 0, 1, back, u32::MAX]);
        text(JOB_TEXT, 0x98a1a0);
        tel26_area_button([bar, 0, 0, 0x30, grey, 0xc, 3, pale, JOB_TEXT as u32, 4, 0]);
        text(JOB_TEXT, 0x98a198);
        tel26_area_button([bar, 1, 0, 0x30, grey, 0xc, 3, pale, JOB_TEXT as u32, 5, 0]);
    }
    exe::drop_text(tx.as_mut_ptr() as *mut usize);
}

/// Rule: on the staff note screen a reminder or reason click chooses it (rebuilding the screen); Confirm saves the
/// note (a new one, or the edit, with the reminder dates when a date was chosen); Delete removes it; Cancel closes.
///
/// `notes_staff_note_screen_handler(item)`: the slot's human, the person (parameter 0), the choice (2), the reason
/// (3), editing (4), the text (5) and the two dates (6, 7). In a network game the pending command argument is cleared
/// and -9 comes back. By the widget's id: 7 (a reminder): parameter 2 = the data's low byte, sign-extended, -11; 3 (a
/// reason): parameter 3 the same, -11; 8 (the text entry): 0; 5 (Confirm): editing, with the choice 0xff and both dates,
/// `Notes::update_note_with_dates(human, person, text, &written, &reminder, reason)` (0x795710, copies of the dates);
/// editing otherwise `Notes::update_note(human, person, text, choice, reason)` (0x7956d0); not editing
/// `Notes::add_note(human, person, text, choice, reason)` (0x7953d0); -9. 6 (Delete): `Notes::delete_note(human,
/// person)` (0x795660), -9. 4 (Cancel): -9. Otherwise the menu bar's command, then its object link.
/// Original: `notes_staff_note_screen_handler` (0x796b30, notes.cpp, cdecl).
pub(crate) unsafe extern "C" fn notes_staff_note_screen_handler(raw: u32) -> i32 {
    let slot = read_i16(G_SCREEN_MANAGER_CURRENT_SLOT) as isize;
    let human = read_usize((G_SCREEN_RECORDS_MANAGER as isize + slot * 0x300) as usize);
    let person = tel36_staff_param(0);
    let choice = get_screen_param(2) as u8 as u32;
    let reason = get_screen_param(3) as u8 as u32;
    let editing = get_screen_param(4) as u8;
    let note_text = get_screen_param(5);
    let written = get_screen_param(6);
    let reminder = get_screen_param(7);
    if read_u32(TEL35_NETWORK_FLAG) != 0 {
        write_u32(G_PENDING_COMMAND_ARG, 0);
        return -9;
    }
    let item = raw as i16;
    match tel26_item_id(item) {
        7 => {
            covered!("tel36_7 staff note reminder choice");
            set_screen_param(2, tel26_item_value(item) as u8 as i8 as isize as usize);
            -11
        }
        3 => {
            covered!("tel36_7 staff note reason");
            set_screen_param(3, tel26_item_value(item) as u8 as i8 as isize as usize);
            -11
        }
        8 => 0,
        5 => {
            covered!("tel36_7 staff note confirm");
            let notes = read_usize(G_NOTES);
            if editing != 0 {
                if choice == 0xff && written != 0 && reminder != 0 {
                    let first = [read_u32(written), read_u32(written + 4)];
                    let second = [read_u32(reminder), read_u32(reminder + 4)];
                    let save: unsafe extern "thiscall" fn(usize, usize, usize, usize, *const u32, *const u32, u32) = core::mem::transmute(FN_NOTES_REPLACE_NOTE_DATED);
                    save(notes, human, person, note_text, first.as_ptr(), second.as_ptr(), reason);
                } else {
                    let save: unsafe extern "thiscall" fn(usize, usize, usize, usize, u32, u32) = core::mem::transmute(FN_NOTES_REPLACE_NOTE);
                    save(notes, human, person, note_text, choice, reason);
                }
            } else {
                exe::notes_add_note(notes, human, person, note_text, choice, reason);
            }
            -9
        }
        6 => {
            notes_call2(0x795660, human, person);
            -9
        }
        4 => -9,
        _ => manager_menu_bar(raw),
    }
}

/// Comparer for `notes_open_staff_note_screen`.
pub(crate) unsafe extern "C" fn compare_notes_open_staff_note_screen(person: usize) {
    // simplification: opening a screen (and setting the edit text) does not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn(usize)>(IDX_NOTES_OPEN_STAFF_NOTE_SCREEN)(person)
}

/// Comparer for `notes_draw_staff_note_screen`: the screen side by side over the display list.
pub(crate) unsafe extern "C" fn compare_notes_draw_staff_note_screen() {
    let o = original_fn::<unsafe extern "C" fn()>(IDX_NOTES_DRAW_STAFF_NOTE_SCREEN);
    compare_by_display_list_with("staff note screen (notes_draw_staff_note_screen)", &[], || o(), || notes_draw_staff_note_screen());
}

/// Comparer for `notes_staff_note_screen_handler`: the reminder and reason choices side by side over the screen
/// params; saving, deleting and the menu bar only the original.
pub(crate) unsafe extern "C" fn compare_notes_staff_note_screen_handler(item: u32) -> i32 {
    let o = original_fn::<unsafe extern "C" fn(u32) -> i32>(IDX_NOTES_STAFF_NOTE_SCREEN_HANDLER);
    if read_u32(TEL35_NETWORK_FLAG) != 0 || !matches!(tel26_item_id(item as i16), 3 | 7 | 8) {
        // simplification: saving or deleting the note and the menu bar commands do not run twice; proven in Rust mode
        return o(item);
    }
    let (r, n, same, mo, mr) = crate::comparison::side_by_side(&screen_param_regions(), || o(item), || notes_staff_note_screen_handler(item));
    SCOREBOARD.record(same && r == n, || format!("staff note screen choice: original={} rust={} differences {:?}", r, n, first_differences(&mo, &mr)));
    r
}

// ---------- batch 318: the competition's official stats tab (officials_manager.cpp) ----------

/// One official stats record of the list (`OfficialsManager::copy_comp_official_stats`, 0x11 bytes): the official's id
/// (+0), the average rating (f32, +4), the yellow cards (i16, +8), the games (i16, +0xc), the harshness (i8, +0xe) and
/// the red cards (u8, +0xf).
const OFFICIAL_STATS_SIZE: usize = 0x11;
const OFFICIAL_STATS_RATING: usize = 0x4;
const OFFICIAL_STATS_YELLOW: usize = 0x8;
const OFFICIAL_STATS_GAMES: usize = 0xc;
const OFFICIAL_STATS_HARSHNESS: usize = 0xe;
const OFFICIAL_STATS_RED: usize = 0xf;
/// The officials.dat record size.
const OFFICIAL_SIZE: u32 = 0x2b;

/// Rule: a competition's official stats tab lists its referees (sorted by games), with their games, red and yellow
/// cards, harshness and average rating, or says there are none.
///
/// `show_comp_official_stats_screen(&comp_id, top, bottom)`: the list of parameter 0x2e and its count (0x2f, a short).
/// `background_set_random_picture`, the menu bar (4, 0) and the heading "Official Stats" as a text item (0x6e, top)-
/// (0x30c, top + 0x23) (font 3, `JOB_COLOUR_BDEC`); the content starts at top + 0x28. With no list: the competition
/// (`competition` record `comp_id`), its count (`OfficialsManager::get_comp_official_count` on `G_OFFICIALS_MANAGER`)
/// and, with any, a `malloc`ed list of count × 0x11 bytes filled by `copy_comp_official_stats` and `qsort`ed by
/// `official_stats_compare_games_desc`; parameters 0x2e and 0x2f get the list (or 0) and the count. With a list and a
/// count: rows = (bottom − start − 0x10) / the height of font 3; area (0x6e, start)-(0x30c, bottom), seven columns (3,
/// 10, 4, 4, 4, 5, 3), kind 2; the headers "Name", "Games", "Red", "Yellow", "Harshness", "Rating" as buttons ids
/// 0x1389..0x138e (Harshness 0x138e, Rating 0x138d) on row 0; then one row per record from row 1: the ordinal of the
/// row, the name ("  <second>" without a first name, "  <i>.<second>" for a one-letter first name, else "  <first>
/// <second>"), the games, the reds, the yellows, the harshness (1 Harsh, 2 Strict, 4 Lenient, otherwise Fair) and the
/// rating ("  %1.2f", or "  ----" when it is 0.0); the area scrolls back to row parameter 0x2c and parameter 0x30 keeps
/// the area. Otherwise the text "There are no official stats available." as a text area. Then the Back / Next
/// buttons.
/// Original: `show_comp_official_stats_screen` (0x79a530, officials_manager.cpp, cdecl).
pub(crate) unsafe extern "C" fn show_comp_official_stats_screen(comp_id: usize, top: i32, bottom: i32) {
    let text = tel36_langlib();
    let format: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_CRT_SPRINTF);
    let columns: [u8; 7] = [3, 0xa, 4, 4, 4, 5, 3];
    let id = read_u32(comp_id);
    let _scroll = get_screen_param(0x2c);
    let mut list = get_screen_param(0x2e);
    let mut count = get_screen_param(0x2f) as i16;
    exe::background_set_random_picture();
    exe::menubar_build(4, 0);
    text(JOB_TEXT, 0xa6a21c);
    type AddTextItem = unsafe extern "thiscall" fn(usize, u32, u32, u32, u32, u32, u32, u32, u32, u32, usize, u32) -> u32;
    let add_text_item: AddTextItem = core::mem::transmute(FN_SCREENMANAGER_ADD_TEXT_ITEM);
    add_text_item(G_SCREEN_MANAGER, 0x6e, top as u32, 0x30c, (top + 0x23) as u32, 2, 0, 0xc, 3, job_colour(JOB_COLOUR_BDEC), JOB_TEXT, 1);
    let start = top + 0x28;
    if list == 0 {
        covered!("tel36_8 official stats list built");
        let comp = read_usize(G_CLUB_COMP_TABLE).wrapping_add(id.wrapping_mul(TEL36_CLUB_COMP_SIZE) as usize);
        count = exe::officialsmanager_get_comp_official_count(read_usize(G_OFFICIALS_MANAGER), comp);
        if count != 0 {
            let n = count as i32;
            list = exe::crt_malloc((n * OFFICIAL_STATS_SIZE as i32) as u32);
            exe::officialsmanager_copy_comp_official_stats(read_usize(G_OFFICIALS_MANAGER), comp, list);
            exe::crt_qsort(list, n as u32, OFFICIAL_STATS_SIZE as u32, 0x79b150usize);
        } else {
            list = 0;
        }
        set_screen_param(0x2e, list);
        set_screen_param(0x2f, count as isize as usize);
    }
    if list != 0 && count != 0 {
        covered!("tel36_8 official stats table");
        let rows = ((bottom - start - 0x10) / exe::font_get_height(3)) as u8 as u32;
        let area = tel26_add_area(current_human_display(), [0x6e, start as u32, 0x30c, bottom as u32, 7, columns.as_ptr() as u32, rows, 0, 2, 0, u32::MAX]);
        let pale = job_colour(JOB_COLOUR_3184);
        let grey = job_colour(JOB_COLOUR_317E);
        for (k, (title, id)) in [(0xa6a214usize, 0x1389u32), (0xa6a20c, 0x138a), (0xa6a204, 0x138b), (0xa6a1f8, 0x138c), (0xa6a1ec, 0x138e), (0xa6a1e0, 0x138d)]
            .into_iter().enumerate() {
            text(JOB_TEXT, title);
            tel26_area_button([area, k as u32 + 1, 0, 0x30, grey, 1, 1, pale, JOB_TEXT as u32, id, 0]);
        }
        let zero = read_f64(rdata::F64_0);
        for k in 0..count as i32 {
            let row = (k + 1) as u32;
            let record = list + k as usize * OFFICIAL_STATS_SIZE;
            let official = read_usize(G_OFFICIAL_TABLE).wrapping_add(read_u32(record).wrapping_mul(OFFICIAL_SIZE) as usize);
            let ordinal = exe::utils_format_ordinal(row as i32, -1);
            tel26_area_text([area, 0, row, 0x30, job_colour(JOB_COLOUR_BE04), 0xc, 1, pale, ordinal as u32]);
            let first = read_usize(official + official::FIRST_NAME);
            let second = read_usize(official + official::SECOND_NAME);
            if read_u8(first) == 0 {
                format(JOB_TEXT, 0x987ff0, second);
            } else if read_u8(first + 1) == 0 {
                format(JOB_TEXT, 0xa6a1d8, read_u8(first) as i8 as i32, second);
            } else {
                format(JOB_TEXT, 0xa6a1d0, first, second);
            }
            tel26_area_text([area, 1, row, 1, 0, 1, 2, pale, JOB_TEXT as u32]);
            for (column, value) in [(2u32, read_i16(record + OFFICIAL_STATS_GAMES) as i32), (3, read_u8(record + OFFICIAL_STATS_RED) as i32),
                (4, read_i16(record + OFFICIAL_STATS_YELLOW) as i32)] {
                format(JOB_TEXT, 0x990b48, value);
                tel26_area_text([area, column, row, 1, 0, 1, 2, pale, JOB_TEXT as u32]);
            }
            let harshness = match read_u8(record + OFFICIAL_STATS_HARSHNESS) as i8 {
                1 => 0xa6a1a8,
                2 => 0xa6a1b0,
                4 => 0xa6a1bc,
                _ => 0xa6a1c8,
            };
            text(JOB_TEXT, harshness);
            tel26_area_text([area, 5, row, 1, 0, 1, 2, pale, JOB_TEXT as u32]);
            let rating = read_f32(record + OFFICIAL_STATS_RATING) as f64;
            if rating == zero || rating.is_nan() {
                format(JOB_TEXT, 0xa6a198);
            } else {
                format(JOB_TEXT, 0xa6a1a0, rating);
            }
            tel26_area_text([area, 6, row, 0x30, job_colour(JOB_COLOUR_3192), 0xc, 1, job_colour(JOB_COLOUR_BDEC), JOB_TEXT as u32]);
        }
        let scroll = get_screen_param(0x2c);
        if area as i16 != -1 {
            exe::area_set_scroll_row(display_area_at(current_human_display(), area as i16), scroll);
        }
        set_screen_param(0x30, area as i16 as isize as usize);
    } else {
        let rows = ((bottom - start - 0x10) / exe::font_get_height(3)) as u8 as u32;
        text(JOB_TEXT, 0xa6a170);
        tel26_text_area([0x6e, start as u32, 0x30c, bottom as u32, 2, 0, rows, 3, job_colour(JOB_COLOUR_3184), JOB_TEXT as u32, 0]);
    }
    tel26_back_next();
}

/// Comparer for `show_comp_official_stats_screen`: the tab side by side over the display list when the list already
/// exists; building the list (`malloc`) only the original.
pub(crate) unsafe extern "C" fn compare_show_comp_official_stats_screen(comp_id: usize, top: i32, bottom: i32) {
    let o = original_fn::<unsafe extern "C" fn(usize, i32, i32)>(IDX_SHOW_COMP_OFFICIAL_STATS_SCREEN);
    if get_screen_param(0x2e) == 0 {
        // simplification: the allocation of the list does not run twice; proven in Rust mode
        return o(comp_id, top, bottom);
    }
    compare_by_display_list_with("official stats tab (show_comp_official_stats_screen)", &[], || o(comp_id, top, bottom), || show_comp_official_stats_screen(comp_id, top, bottom));
}

// ---------- batch 318: the staff profile actions and the compare players dialog (staff_screens.cpp) ----------

/// A cdecl screen opener by address with one argument.
unsafe fn staff_action1(f: usize, a: usize) {
    let g: unsafe extern "C" fn(usize) = core::mem::transmute(f);
    g(a)
}

/// A cdecl screen opener by address with two arguments.
unsafe fn staff_action2(f: usize, a: usize, b: usize) {
    let g: unsafe extern "C" fn(usize, usize) = core::mem::transmute(f);
    g(a, b)
}

/// A cdecl screen opener by address with three arguments.
unsafe fn staff_action3(f: usize, a: usize, b: usize, c: usize) {
    let g: unsafe extern "C" fn(usize, usize, usize) = core::mem::transmute(f);
    g(a, b, c)
}

/// A cdecl screen opener by address with four arguments.
unsafe fn staff_action4(f: usize, a: usize, b: usize, c: usize, d: usize) {
    let g: unsafe extern "C" fn(usize, usize, usize, usize) = core::mem::transmute(f);
    g(a, b, c, d)
}

/// `confirm_push(title, heading, message, yes/no, colour, colour, dialog code)` (0x591840, cdecl): a message box.
unsafe fn staff_confirm_push(title: usize, heading: usize, message: usize, yes_no: u32, a: u32, b: u32, code: u32) {
    exe::confirm_push(title, heading, message, yes_no, a, b, code)
}

/// The message box of a profile action that cannot be done: the message (already in the screens' text buffer, `message`
/// as the formatter answered), the heading `heading` (a language text into a local buffer), the person's name as the
/// title, OK only, the two colours and the dialog code.
unsafe fn staff_cannot_box(name: usize, heading: usize, message: usize, colours: (u32, u32), code: u32) {
    let mut buffer = [0u8; 0xc8];
    let h = tel36_langlib()(buffer.as_mut_ptr() as usize, heading) as u32 as usize;
    staff_confirm_push(name, h, message, 0, colours.0, colours.1, code);
}

/// `TRANSFER_MANAGER::can_club_bid_for_player(person, club, &reason, 0)` (0x8ce990, thiscall, ret 0x10).
unsafe fn staff_can_bid(person: usize, club: usize, reason: &mut u32) -> u32 {
    exe::transfer_manager_can_club_bid_for_player(read_usize(G_TRANSFER_MANAGER), person, club, (reason) as *mut u32 as *mut u16, 0)
}

/// `transfer_screens_open_cannot_sign_dialog(person, club, reason, kind)` (0x8f0e40, cdecl).
unsafe fn staff_cannot_sign(person: usize, club: usize, reason: u32, kind: usize) {
    staff_action4(0x8f0e40, person, club, reason as usize, kind)
}

/// Rule: the staff profile and compare screens answer their action menu: view, history, votes, squad moves,
/// shortlists, notes, treatments, reports, contracts, transfer and loan offers, scouting, nicknames, the tab choices;
/// what is not an action goes to the profile tab answer and then the menu bar.
///
/// `staff_screens_handle_compare_action(item)`: the person (parameter 0), the two colours (0x11, 0x12) and the slot's
/// human. In a network game the pending command (`G_PENDING_COMMAND` 0xdd6be0, argument `G_PENDING_COMMAND_ARG`): 0x18
/// clears both and, with the argument 2, casts the human's vote for the person in the shortlist of parameter 0xd
/// (`AWARD_SHORTLIST::cast_vote`, at +0x1f) and answers -10, otherwise clears parameter 0xd; 0x27, 0x42 and 0x3c clear
/// both. Then by the widget's id (read again at each test): 0x3c / 0x3d: parameter 0x14 = 1 / 0, -11. 1: the profile of
/// the widget's person (`staff_screens_open_staff_profile(person, 1, 1, 1, 0)`). 0x1f: the terminate contract screen.
/// 0x1e: the history screen with "<first> <second> <day>.<month>.<year>" of the birth date. 2: the vote confirm box
/// for the award entry of the widget (parameter 0xd = the entry; colours of its competition, of its nation's national
/// team, or of the World Cup; "Vote for <name> for the <award> award ?", heading "Please Confirm", title "Vote For
/// Award", yes/no, code 0x18). 3: `CONTRACT_MANAGER::toggle_squad_placement(person, human club, &club)`; failing, the box
/// "There is no space in the <club> squad..." / "Cannot move player to squad" (code 0x27); else -11. 0x1d: the club
/// shortlists of `G_TRANSFER_MANAGER`'s shortlist manager (+0x856) take the person (when there is one), -11. 0x2c: the
/// staff note screen. 0x2e / 0x2d: the treatment confirm screen (leave 1 / 0). 0x2a: the coach report request with the
/// club's exe::database_get_club_assistant(the linked B team's when it is not a reserve) or the first of the five coaches other than the
/// person; -11. 0x2b: the physio report with the club's first physio; -11. 0x23: `staff_normalise_player_attributes`,
/// -11. 5: the transfer status screen. 0x24: the discipline screen. 6: with an agreed contract
/// (`TRANSFER_MANAGER::get_agreed_contract_club`), the box "<name> has already accepted a contract offer from <club>."
/// / "Cannot offer contract" (code 0x3c), else the contract offer (0, 0, 0). 7 / 8 and 0x19 / 0x1a: the transfer list
/// dialog (0 / 1). 9: the release dialog. 0xa / 0xb: the shortlist dialog (0 / 1). 0xc: the contract offer of the
/// widget's kind. 0xd: the widget's offer: status 2 the offer changed screen, else the withdraw dialog. 0xe: the bid
/// screen with the widget's offer slot. 0xf, 0x10, 0x17, 0x16: `can_club_bid_for_player` for the human's club; refused,
/// the cannot sign dialog (kind 3, 0, 2, 1); allowed: 0xf the contract offer (0, 1, 0), 0x10 the bid screen (only for a
/// person with a club, else on to the next tests), 0x17 the trial dialog, 0x16 the loan period
/// (`TRANSFER_MANAGER::get_loan_period`) and, when its start is before its end, the cannot sign dialog (kind 1), else
/// the loan bid screen. 0x18: the end loan dialog. 0x11: a widget data other than parameter 1 becomes parameter 1,
/// -11 (else on). 0x13: the bid screen of the widget's offer. 0x1b / 0x1c: the squad move screen (1 / 0). 0x25, 0x26:
/// the nickname dialog with a 26-byte buffer of the human's nickname for the person, or his common name. 0x29: the
/// scouting: by `SCOUT_MANAGER::get_scout_request_status` 0 / 1 the scout request dialog (parameter 1 = 1 / 0), 2 / 4 /
/// 3 the boxes "no scouts" / "no resources" / "already scouting" (code 0x42); then `SCOUT_MANAGER::add_to_shortlist`.
/// Otherwise `staff_screens_handle_profile_tab_action`, then the menu bar. Actions answer -4 unless said.
/// Original: `staff_screens_handle_compare_action` (0x889c30, staff_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn staff_screens_handle_compare_action(raw: u32) -> i32 {
    let text = tel36_langlib();
    let format: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_CRT_SPRINTF);
    let person = Staff(get_screen_param(0));
    let mut colours = (get_screen_param(0x11) as u32, get_screen_param(0x12) as u32);
    let slot = read_i16(G_SCREEN_MANAGER_CURRENT_SLOT) as isize;
    let human = read_usize((G_SCREEN_RECORDS_MANAGER as isize + slot * 0x300) as usize);
    let shortlist_vote = |human: usize| {
        exe::award_shortlist_cast_vote(read_usize(get_screen_param(0xd) + 0x1f), human, person.addr());
    };
    if read_u32(TEL35_NETWORK_FLAG) != 0 {
        let mut command = read_u32(STAFF_PENDING_COMMAND);
        if command == 0x18 {
            let argument = read_u32(G_PENDING_COMMAND_ARG);
            write_u32(STAFF_PENDING_COMMAND, 0);
            write_u32(G_PENDING_COMMAND_ARG, 0);
            if argument == 2 {
                covered!("tel36_9 network vote");
                shortlist_vote(human);
                set_screen_param(0xd, 0);
                return -10;
            }
            set_screen_param(0xd, 0);
            command = read_u32(STAFF_PENDING_COMMAND);
        }
        if matches!(command, 0x27 | 0x42 | 0x3c) {
            write_u32(G_PENDING_COMMAND_ARG, 0);
            write_u32(STAFF_PENDING_COMMAND, 0);
        }
    }
    let item = raw as i16;
    let id = || tel26_item_id(item);
    let value = || tel26_item_value(item) as usize;
    let mut name = [0u8; 0xc8];
    let n = name.as_mut_ptr() as usize;
    match id() {
        0x3c | 0x3d => {
            set_screen_param(0x14, (id() == 0x3c) as usize);
            return -11;
        }
        1 => {
            exe::staff_screens_open_staff_profile((value()) as usize as u32, 1, 1, 1, 0);
        }
        0x1f => staff_action1(0x4e53e0, person.addr()),
        0x1e => {
            covered!("tel36_9 person history");
            let second = if read_usize(person.addr() + 8) != 0 { read_usize(person.addr() + 8) } else { 0x989ad8 };
            let first = if read_usize(person.addr() + 4) != 0 { read_usize(person.addr() + 4) } else { 0x989ad8 };
            let born = person.addr() + 0x10;
            let year = read_u16(person.addr() + 0x12) as u32;
            let month = exe::date_get_month(born) as i8 as i32 + 1;
            let day = exe::date_get_day_of_month(born) as i16 as i32;
            format(JOB_TEXT, 0x9ced08, first, second, day, month, year);
            staff_action1(0x5f11c0, JOB_TEXT);
        }
        2 => {
            covered!("tel36_9 award vote box");
            let entry = value();
            let award = read_usize(read_usize(read_usize(G_AWARD_MANAGER) + 8) + read_u32(entry + 0xd) as usize * 4);
            set_screen_param(0xd, entry);
            exe::database_format_staff_name(person, n, 0xc8, 1);
            let comp = read_usize(entry + 9);
            if comp != 0 {
                exe::database_get_comp_colours(comp, &mut colours.0, &mut colours.1);
            } else if read_u8(award + 0x12) == 1 {
                exe::database_get_club_kit_colours(exe::database_get_national_team(read_usize(award + 0xe)), 1, &mut colours.0, &mut colours.1);
            } else {
                let world_cup = read_usize(G_CLUB_COMP_TABLE).wrapping_add(read_u32(KEY_CLUB_COMP_FIFA_WORLD_CUP).wrapping_mul(TEL36_CLUB_COMP_SIZE) as usize);
                exe::database_get_comp_colours(world_cup, &mut colours.0, &mut colours.1);
            }
            let message = text(JOB_TEXT, 0xa8b320, n, read_usize(entry + 5) + 4) as u32 as usize;
            let (mut heading, mut title) = ([0u8; 0xc8], [0u8; 0xc8]);
            let h = text(heading.as_mut_ptr() as usize, 0x9909b8) as u32 as usize;
            let t = text(title.as_mut_ptr() as usize, 0xa8562c) as u32 as usize;
            staff_confirm_push(t, h, message, 1, colours.0, colours.1, 0x18);
        }
        3 => {
            let club = read_usize(human + staff::CLUB_JOB);
            let mut full = 0usize;
            if exe::contract_manager_toggle_squad_placement(read_usize(G_CONTRACT_MANAGER), person.addr(), club, (&mut full) as *mut usize as usize) != 0 {
                return -11;
            }
            covered!("tel36_9 no space in the squad");
            exe::database_format_staff_name(person, n, 0xc8, 1);
            exe::database_get_club_kit_colours(club, 1, &mut colours.0, &mut colours.1);
            let gender = read_u8(full + club::SHORT_GENDER_NAME) as i8 as i32;
            let message = text(JOB_TEXT, 0xa8b2cc, gender, gender, full + club::SHORT_NAME) as u32 as usize;
            staff_cannot_box(n, 0xa8b2b0, message, colours, 0x27);
        }
        0x1d => {
            let tm = read_usize(G_TRANSFER_MANAGER);
            if tm != 0 && read_usize(tm + 0x856) != 0 {
                let add: unsafe extern "thiscall" fn(usize, usize, u32) = core::mem::transmute(FN_SHORTLIST_MANAGER_ADD_PLAYER_TO_CLUB_SHORTLISTS);
                add(read_usize(tm + 0x856), person.addr(), 1);
            }
            return -11;
        }
        0x2c => staff_action1(0x7961b0, person.addr()),
        0x2e => staff_action2(0x7e5b10, person.addr(), 1),
        0x2d => staff_action2(0x7e5b10, person.addr(), 0),
        0x2a => {
            let mut club = person.club_job().addr();
            if club == 0 {
                return -11;
            }
            // the original's flag is the frame slot that holds the human until the call writes it
            let mut reserve = human as u32;
            let b_team = exe::club_get_linked_b_team(club, &mut reserve, 1);
            if b_team != 0 && reserve == 0 {
                club = b_team;
            }
            let mut coach = exe::database_get_club_assistant(club);
            if coach == person.addr() {
                coach = 0;
            }
            if coach == 0 {
                coach = (0..5).map(|k| read_usize(club + club::COACHES + 4 * k)).find(|&c| c != 0 && c != person.addr()).unwrap_or(0);
            }
            if coach != 0 {
                covered!("tel36_9 coach report");
                staff_action2(0x48bc00, person.addr(), coach);
            }
            return -11;
        }
        0x2b => {
            let club = person.club_job().addr();
            if club != 0 {
                if let Some(physio) = (0..3).map(|k| read_usize(club + club::PHYSIOS + 4 * k)).find(|&p| p != 0) {
                    staff_action2(0x7a2a50, person.addr(), physio);
                }
            }
            return -11;
        }
        0x23 => {
            staff_action1(FN_STAFF_NORMALISE_PLAYER_ATTRIBUTES, person.addr());
            return -11;
        }
        5 => staff_action4(0x8f6770, person.addr(), 0, usize::MAX, 0),
        0x24 => staff_action1(0x5a8380, person.addr()),
        6 => {
            let mut club = 0usize;
            if exe::transfer_manager_get_agreed_contract_club(read_usize(G_TRANSFER_MANAGER), person.addr(), (&mut club) as *mut usize as usize) != 0 {
                covered!("tel36_9 contract already agreed");
                exe::database_format_staff_name(person, n, 0xc8, 1);
                let gender = read_u8(club + club::SHORT_GENDER_NAME) as i8 as i32;
                let message = text(JOB_TEXT, 0xa8b23c, gender, gender, n, club + club::SHORT_NAME) as u32 as usize;
                staff_cannot_box(n, 0xa8b224, message, colours, 0x3c);
            } else {
                staff_action4(0x4dd0f0, person.addr(), 0, 0, 0);
            }
        }
        7 | 8 => staff_action2(0x8f8120, person.addr(), 0),
        0x19 | 0x1a => staff_action2(0x8f8120, person.addr(), 1),
        9 => staff_action1(0x8f8630, person.addr()),
        0xa => staff_action2(0x8f4160, person.addr(), 0),
        0xb => staff_action2(0x8f4160, person.addr(), 1),
        0xc => staff_action4(0x4dd0f0, person.addr(), value(), 1, 0),
        0xd => {
            let slot = value();
            let offer = Offer(read_usize(slot));
            if offer.status() == 2 {
                staff_action2(0x8f2470, offer.addr(), (offer.serial() as u32) as usize);
            } else {
                staff_action1(0x8f4c70, slot);
            }
        }
        0xe => staff_action2(0x8e9350, person.addr(), value()),
        0xf | 0x10 | 0x17 | 0x16 => {
            let action = id();
            let club = read_usize(human + staff::CLUB_JOB);
            let mut reason = 0u32;
            if staff_can_bid(person.addr(), club, &mut reason) == 0 {
                covered!("tel36_9 cannot sign");
                let kind = match action { 0xf => 3, 0x10 => 0, 0x17 => 2, _ => 1 };
                staff_cannot_sign(person.addr(), read_usize(human + staff::CLUB_JOB), reason, kind);
            } else {
                match action {
                    0xf => staff_action4(0x4dd0f0, person.addr(), 0, 1, 0),
                    0x10 => {
                        if person.club_job().addr() == 0 {
                            return staff_compare_default(raw);
                        }
                        staff_action2(0x8e9350, person.addr(), 0);
                    }
                    0x17 => staff_action1(0x8f8be0, person.addr()),
                    _ => {
                        covered!("tel36_9 loan bid");
                        let contract = Contract(exe::contract_manager_get_contract(read_usize(G_CONTRACT_MANAGER), person));
                        write_usize(G_CONTRACT_LOOKUP_RESULT, contract.addr());
                        let seller = if !contract.is_null() {
                            read_usize(G_CLUB_TABLE).wrapping_add((contract.club() as u32).wrapping_mul(club::SIZE as u32) as usize)
                        } else {
                            0
                        };
                        let (mut a, mut b, mut c, mut d) = (0u32, 0u32, 0u32, 0u32);
                        let period: unsafe extern "thiscall" fn(usize, usize, usize, usize, *mut u32, *mut u32, *mut u32, *mut u32) =
                            core::mem::transmute(FN_TRANSFER_MANAGER_GET_LOAN_PERIOD);
                        period(read_usize(G_TRANSFER_MANAGER), read_usize(human + staff::CLUB_JOB), seller, person.addr(), &mut a, &mut b, &mut c, &mut d);
                        let (mut start, mut end) = ([0u16; 4], [0u16; 4]);
                        exe::date_date_549f70(&mut start, 1, c, d, u32::MAX);
                        exe::date_date_549f70(&mut end, 1, a, b, u32::MAX);
                        let earlier = if start[1] != end[1] { start[1] < end[1] } else { (start[0] as i16) < (end[0] as i16) };
                        if earlier {
                            staff_cannot_sign(person.addr(), read_usize(human + staff::CLUB_JOB), reason, 1);
                        } else {
                            staff_action1(0x8f9690, person.addr());
                        }
                    }
                }
            }
        }
        0x18 => staff_action1(0x8fbcc0, person.addr()),
        0x11 if value() != get_screen_param(1) => {
            set_screen_param(1, value());
            return -11;
        }
        0x13 => staff_action2(0x8e9550, value(), 1),
        0x1b => staff_action3(0x778f60, person.addr(), value(), 1),
        0x1c => staff_action3(0x778f60, person.addr(), value(), 0),
        0x25 | 0x26 => {
            covered!("tel36_9 nickname dialog");
            let buffer = exe::crt_malloc(0x1a);
            if exe::screenmanager_open_screen(G_SCREEN_MANAGER, 0x88bc70usize, 0x88bee0usize, 1, 0usize, 0) != 0 {
                set_screen_param(0, person.addr());
                let manager = read_usize(G_HUMAN_MANAGER);
                let source = if exe::human_manager_has_nickname(manager, person.addr(), 0) != 0 {
                    exe::human_manager_get_nickname(manager, person.addr(), 0)
                } else {
                    read_usize(person.addr() + 0xc)
                };
                tel26_copy_text(buffer as *mut u8, source as *const u8);
                set_screen_param(1, buffer);
            }
        }
        0x29 => {
            covered!("tel36_9 scouting");
            let club = read_usize(human + staff::CLUB_JOB);
            exe::database_format_staff_name(person, n, 0xc8, 1);
            exe::database_get_club_kit_colours(club, 1, &mut colours.0, &mut colours.1);
            match exe::scout_manager_get_scout_request_status(read_usize(G_SCOUT_MANAGER), person.addr(), 0) as i8 {
                s @ (0 | 1) => {
                    if exe::screenmanager_open_screen(G_SCREEN_MANAGER, 0x88c100usize, 0x88c360usize, 1, 0usize, 0) != 0 {
                        set_screen_param(0, read_u32(person.addr()) as usize);
                        set_screen_param(1, (s == 0) as usize);
                    }
                }
                s @ (2 | 3 | 4) => {
                    let (question, heading) = match s { 2 => (0xa8b1e4, 0xa8b1c8), 4 => (0xa8b16c, 0xa8b1c8), _ => (0xa8b144, 0xa8b134) };
                    let message = text(JOB_TEXT, question) as u32 as usize;
                    staff_cannot_box(n, heading, message, colours, 0x42);
                }
                _ => {}
            }
            let add: unsafe extern "thiscall" fn(usize, usize, u32) = core::mem::transmute(FN_SCOUT_MANAGER_ADD_TO_SHORTLIST);
            add(read_usize(G_SCOUT_MANAGER), person.addr(), 0);
        }
        _ => return staff_compare_default(raw),
    }
    -4
}

/// The pending network command (0xdd6be0; its argument is `G_PENDING_COMMAND_ARG`).
const STAFF_PENDING_COMMAND: usize = 0xdd6be0;

/// The answer of the compare actions to a widget that is not an action: the profile tab answer, then the menu bar.
unsafe fn staff_compare_default(raw: u32) -> i32 {
    let r = staff_screens_handle_profile_tab_action(raw);
    if r != 0 {
        return r;
    }
    manager_menu_bar(raw)
}

/// Rule: on the profile tab the attribute view (id 0x12) switches to the widget's view, and "-" / "+" (0x27 / 0x28)
/// move the zoom (parameter 0x13) between 0 and 3.
///
/// `staff_screens_handle_profile_tab_action(item)`: 0x12 with a widget data other than parameter 4: parameter 4 = the
/// data, -11. 0x27 with parameter 0x13 (a char) above 0: one less, -11. 0x28 with parameter 0x13 + 1 below 4: that,
/// -11. Otherwise 0.
/// Original: `staff_screens_handle_profile_tab_action` (0x88b2f0, staff_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn staff_screens_handle_profile_tab_action(raw: u32) -> i32 {
    let item = raw as i16;
    if tel26_item_id(item) == 0x12 && tel26_item_value(item) as usize != get_screen_param(4) {
        covered!("tel36_9 profile view");
        set_screen_param(4, tel26_item_value(item) as usize);
        return -11;
    }
    if tel26_item_id(item) == 0x27 {
        let zoom = get_screen_param(0x13) as u8 as i8;
        if zoom > 0 {
            set_screen_param(0x13, (zoom as i32 - 1) as usize);
            return -11;
        }
    }
    if tel26_item_id(item) == 0x28 {
        let zoom = get_screen_param(0x13) as u8 as i8 as i32 + 1;
        if zoom < 4 {
            set_screen_param(0x13, zoom as usize);
            return -11;
        }
    }
    0
}

/// Rule: on the history tab the list keeps its scroll, the filters (0x14) toggle the low five bits of the history
/// mode, the season chooser (0x20, 0x21, 0x22) moves the page, the 0x3e / 0x3f switch the detail and 0x15 picks the row.
///
/// `staff_screens_handle_history_tab_action(item)`: the person (parameter 0), the mode (5), the season (0xe), the page
/// (0xf) and the last page (0x10). For no person or one of the regular staff (id below `G_STAFF_COUNT`), with a widget:
/// parameter 9 = the scroll row of the area in parameter 0xa. By the widget's id: 0x14 with a data sharing no bit with
/// the mode: data 1, 2, 4, 8 or 16 replaces the low five bits of the mode (parameter 5); any other value only answers;
/// -11. 0x20: a season other than parameter 0xe goes there; the page goes back to 1; -11. 0x3e / 0x3f: parameter 0x15 =
/// 1 / 0, -11. 0x21: the page − 1 (at least 1), -11. 0x22: the page + 1 (at most the last page), -11. 0x15: parameter
/// 8 = the data, -11. Otherwise 0.
/// Original: `staff_screens_handle_history_tab_action` (0x88b4b0, staff_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn staff_screens_handle_history_tab_action(raw: u32) -> i32 {
    let person = get_screen_param(0);
    let mode = get_screen_param(5) as u32;
    let season = get_screen_param(0xe);
    let page = get_screen_param(0xf) as u16 as i16 as i32;
    let last = get_screen_param(0x10) as u16 as i16 as i32;
    let item = raw as i16;
    if (person == 0 || read_i32(person) < read_i32(G_STAFF_COUNT)) && item != -1 {
        let row = exe::screenmanager_get_area_scroll_row(G_SCREEN_MANAGER, get_screen_param(0xa));
        set_screen_param(9, row);
    }
    let id = || tel26_item_id(item);
    let value = || tel26_item_value(item);
    if id() == 0x14 && mode & value() == 0 {
        covered!("tel36_9 history filter");
        let v = value();
        if matches!(v, 1 | 2 | 4 | 8 | 0x10) {
            set_screen_param(5, ((mode & !0x1f) | v) as usize);
        }
        return -11;
    }
    match id() {
        0x20 => {
            if season != value() as usize {
                set_screen_param(0xe, value() as usize);
            }
            set_screen_param(0xf, 1);
            -11
        }
        0x3e | 0x3f => {
            set_screen_param(0x15, (id() == 0x3e) as usize);
            -11
        }
        0x21 => {
            set_screen_param(0xf, (page - 1).max(1) as usize);
            -11
        }
        0x22 => {
            set_screen_param(0xf, (page + 1).min(last) as isize as usize);
            -11
        }
        0x15 => {
            set_screen_param(8, value() as usize);
            -11
        }
        _ => 0,
    }
}

/// Rule: leaving the staff profile frees its lists.
///
/// `staff_screens_leave_profile_screen()`: the list of parameter 3 (an LLIST, destroyed and deleted) and the buffer of
/// parameter 6 (`free`), each cleared when present.
/// Original: `staff_screens_leave_profile_screen` (0x88b8a0, staff_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn staff_screens_leave_profile_screen() {
    let list = get_screen_param(3);
    let buffer = get_screen_param(6);
    if list != 0 {
        covered!("tel36_9 leave the profile frees the list");
        exe::drop_llist(list);
        exe::crt_operator_delete(list);
        set_screen_param(3, 0);
    }
    if buffer != 0 {
        exe::crt_free(buffer);
        set_screen_param(6, 0);
    }
}

