    exe::crt_free(teams);
    exe::crt_free(table);
    let group = read_usize(this.stages() + stage as usize * 4);
    if group == 0 {
        show_error_at(0xa6a0ec, 0x347);
        return 0;
    }
    this.set_current_stage((stage) as usize);
    exe::league_send_group_draw_news(group);
